@font-face {
  font-family: 'Barlow Condensed';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/barlowcondensed/v13/HTxwL3I-JCGChYJ8VI-L6OO_au7B46r2_3E.ttf) format('truetype');
}

input.content:
/* ============================================================
   AIRBALL — 2 Player Street Basketball
   UI / HUD / Screens
   ============================================================ */

:root{
  --ink:#05070c;
  --ink-2:#0a0f18;
  --panel:rgba(10,15,24,.86);
  --panel-2:rgba(16,23,36,.92);
  --line:rgba(255,255,255,.10);
  --line-soft:rgba(255,255,255,.055);
  --txt:#eef3fb;
  --txt-dim:#9fb0c6;
  --txt-mute:#65758c;
  --orange:#ff7a1a;
  --orange-2:#ffa53c;
  --gold:#ffc857;
  --cyan:#3ce0ff;
  --pink:#ff4d7e;
  --lime:#c8ff4d;
  --p1:#37d9ff;
  --p2:#ff6440;
  --font-display:"Bahnschrift","DIN Alternate","Arial Narrow","Roboto Condensed","Helvetica Neue",sans-serif;
  --font-body:"Segoe UI Variable Display","Segoe UI",system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;
}

*{margin:0;padding:0;box-sizing:border-box;}
html,body{height:100%;}
body{
  background:
    radial-gradient(1200px 700px at 50% 30%, #0b1220 0%, #05070c 60%, #020306 100%);
  color:var(--txt);
  font-family:var(--font-body);
  overflow:hidden;
  user-select:none;
  -webkit-user-select:none;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}
button{font-family:inherit;color:inherit;border:0;background:none;cursor:pointer;}
.svg-defs{position:absolute;width:0;height:0;overflow:hidden;}
svg{display:block;}

#app{
  position:fixed;inset:0;
  display:grid;place-items:center;
  overflow:hidden;
}
#stage{
  position:relative;
  width:1600px;height:900px;
  flex:0 0 auto;
  transform-origin:center center;
  background:#04060b;
  overflow:hidden;
  box-shadow:0 40px 140px rgba(0,0,0,.8);
}
#game{position:absolute;inset:0;display:block;width:1600px;height:900px;}

/* ============================== shared bits ============================== */
.is-hidden{display:none !important;}

.icon-btn{
  width:44px;height:44px;border-radius:12px;
  display:grid;place-items:center;
  background:rgba(13,20,32,.72);
  border:1px solid var(--line);
  color:#cfe0f5;
  backdrop-filter:blur(10px);
  transition:.18s ease;
  position:relative;
}
.icon-btn svg{width:19px;height:19px;}
.icon-btn:hover{background:rgba(30,44,66,.9);color:#fff;border-color:rgba(255,255,255,.24);transform:translateY(-1px);}
.icon-btn:active{transform:translateY(0) scale(.96);}
.icon-btn.ghost{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.08);}

/* ============================== HUD ============================== */
.hud{position:absolute;inset:0;z-index:5;pointer-events:none;}
.hud button{pointer-events:auto;}

/* ---- scoreboard ---- */
.scoreboard{
  position:absolute;top:22px;left:50%;transform:translateX(-50%);
  width:790px;height:104px;
  display:flex;align-items:stretch;
  background:
    linear-gradient(180deg,rgba(24,33,49,.94),rgba(8,12,20,.94));
  border:1px solid rgba(255,255,255,.13);
  border-radius:16px;
  box-shadow:
    0 18px 50px rgba(0,0,0,.65),
    inset 0 1px 0 rgba(255,255,255,.14),
    inset 0 0 60px rgba(80,140,255,.05);
  overflow:hidden;
  backdrop-filter:blur(14px);
}
.scoreboard:before{
  content:"";position:absolute;inset:0;
  background:
    repeating-linear-gradient(90deg,rgba(255,255,255,.018) 0 1px,transparent 1px 3px);
  pointer-events:none;
  opacity:.5;
}
.sb-side{
  position:relative;
  flex:1;display:flex;align-items:center;gap:14px;
  padding:0 22px;
  min-width:0;
}
.sb-side.sb-p2{justify-content:flex-end;}
.sb-color{
  position:absolute;top:0;bottom:0;width:5px;
  background:var(--p1);
  box-shadow:0 0 18px var(--p1);
}
.sb-p1 .sb-color{left:0;}
.sb-p2 .sb-color{right:0;background:var(--p2);box-shadow:0 0 18px var(--p2);}
.sb-score{
  font-family:var(--font-display);
  font-weight:700;
  font-size:58px;line-height:.9;
  letter-spacing:-1px;
  color:#fff;
  text-shadow:0 3px 0 rgba(0,0,0,.4),0 0 34px rgba(120,190,255,.18);
  font-variant-numeric:tabular-nums;
  min-width:64px;
  transition:transform .14s cubic-bezier(.2,1.8,.4,1);
}
.sb-score.pop{transform:scale(1.28);}
.sb-p2 .sb-score{text-align:right;}
.sb-info{display:flex;flex-direction:column;gap:3px;min-width:0;}
.sb-info-r{text-align:right;align-items:flex-end;}
.sb-nameline{font-family:var(--font-display);font-weight:700;font-size:24px;letter-spacing:.5px;line-height:1;white-space:nowrap;}
.sb-nameline em{font-style:normal;font-size:15px;color:var(--txt-mute);margin-left:6px;letter-spacing:0;}
.sb-teamline{display:flex;align-items:center;gap:7px;font-size:10px;letter-spacing:.18em;color:var(--txt-mute);font-weight:600;}
.sb-fire{display:none;width:15px;height:15px;color:var(--orange-2);filter:drop-shadow(0 0 6px rgba(255,140,40,.9));animation:flicker 1.1s infinite;}
.sb-fire svg{width:15px;height:15px;}
.sb-side.on-fire .sb-fire{display:block;}
.sb-side.on-fire .sb-nameline{color:var(--gold);text-shadow:0 0 18px rgba(255,170,50,.55);}

.sb-mid{
  width:196px;flex:0 0 196px;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  position:relative;
  background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(0,0,0,.12));
  border-left:1px solid rgba(255,255,255,.07);
  border-right:1px solid rgba(255,255,255,.07);
}
.sb-clock{
  font-family:var(--font-display);font-weight:700;
  font-size:44px;line-height:.92;letter-spacing:0;
  font-variant-numeric:tabular-nums;
  color:#fff;
  text-shadow:0 2px 0 rgba(0,0,0,.5);
}
.sb-clock.low{color:#ff8a6b;animation:pulseSoft .9s infinite;}
.sb-sub{display:flex;align-items:center;gap:6px;margin-top:4px;font-size:10px;letter-spacing:.12em;font-weight:700;color:var(--txt-mute);}
.sb-q{color:var(--gold);letter-spacing:.14em;}
.sb-sep{width:1px;height:10px;background:rgba(255,255,255,.16);}
.sb-shotlabel{font-size:8px;letter-spacing:.16em;}
.sb-shot{color:#fff;font-size:12px;font-variant-numeric:tabular-nums;}
.sb-shot.low{color:#ff6a4d;}
.sb-quarters{display:flex;gap:5px;margin-top:6px;}
.sb-quarters i{width:16px;height:3px;border-radius:2px;background:rgba(255,255,255,.14);transition:.2s;}
.sb-quarters i.done{background:rgba(255,255,255,.45);}
.sb-quarters i.cur{background:var(--gold);box-shadow:0 0 10px rgba(255,200,80,.7);}

/* ---- bench HUD ---- */
.bench-hud{
  position:absolute;bottom:24px;
  display:flex;align-items:flex-end;gap:12px;
  width:356px;
  padding:10px 14px 11px;
  border-radius:14px;
  background:linear-gradient(180deg,rgba(16,23,36,.82),rgba(7,11,18,.9));
  border:1px solid rgba(255,255,255,.1);
  box-shadow:0 14px 34px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter:blur(10px);
  overflow:hidden;
}
.bench-hud.p1{left:26px;border-left:3px solid var(--p1);}
.bench-hud.p2{right:26px;border-right:3px solid var(--p2);justify-content:flex-end;}
.bh-portrait{
  position:relative;width:64px;height:76px;flex:0 0 64px;
  border-radius:9px;overflow:hidden;
  background:linear-gradient(160deg,#1b2740,#0a101b);
  border:1px solid rgba(255,255,255,.14);
  margin-top:-22px;
  box-shadow:0 8px 18px rgba(0,0,0,.5);
}
.bh-portrait canvas{width:100%;height:100%;display:block;transform:scale(1.34) translateY(7%);}
.bh-tag{
  position:absolute;left:0;right:0;bottom:0;
  font-size:8px;letter-spacing:.16em;font-weight:800;text-align:center;
  padding:2px 0;background:rgba(0,0,0,.62);
}
.p1 .bh-tag{color:var(--p1);}
.p2 .bh-tag{color:var(--p2);}
.bh-body{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px;}
.bench-hud.p2 .bh-body{align-items:flex-end;}
.bh-name{font-family:var(--font-display);font-weight:700;font-size:19px;letter-spacing:.4px;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;}
.bh-sub{font-size:9px;letter-spacing:.14em;color:var(--txt-mute);font-weight:600;}
.bh-bar{
  width:100%;height:5px;border-radius:3px;overflow:hidden;
  background:rgba(255,255,255,.08);
  margin-top:2px;
  position:relative;
}
.bh-bar i{
  display:block;height:100%;width:100%;
  background:linear-gradient(90deg,#28e0a0,#7bffca);
  border-radius:3px;
  transition:width .12s linear,background .2s;
  box-shadow:0 0 10px rgba(60,255,190,.4);
}
.bh-bar i.mid{background:linear-gradient(90deg,#ffc247,#ffe28a);box-shadow:0 0 10px rgba(255,200,80,.4);}
.bh-bar i.low{background:linear-gradient(90deg,#ff4d3d,#ff8a5a);box-shadow:0 0 10px rgba(255,90,70,.5);}
.bh-keys{
  display:flex;align-items:center;gap:3px;
  font-size:8px;letter-spacing:.1em;color:var(--txt-mute);
  margin-top:2px;white-space:nowrap;
}
.bh-keys b{
  min-width:17px;height:17px;padding:0 4px;border-radius:4px;
  display:inline-flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);
  color:#cfdcee;font-size:9px;font-weight:700;
}
.bh-keys .key-main{background:rgba(255,122,26,.16);border-color:rgba(255,122,26,.45);color:#ffb877;}
.bh-keys span{margin:0 4px 0 2px;}

.hud-topright{position:absolute;top:26px;right:26px;display:flex;gap:8px;}
.control-strip{
  position:absolute;left:50%;bottom:26px;transform:translateX(-50%);
  display:flex;align-items:center;gap:14px;
  padding:8px 18px;border-radius:99px;
  background:rgba(8,12,20,.62);
  border:1px solid rgba(255,255,255,.08);
  font-size:10px;letter-spacing:.09em;color:var(--txt-mute);
  backdrop-filter:blur(8px);
  white-space:nowrap;
  transition:opacity .5s;
}
.control-strip b{font-weight:800;letter-spacing:.14em;}
.control-strip b:first-child{color:var(--p1);}
.control-strip span:last-child b{color:var(--p2);}
.control-strip em{
  font-style:normal;color:#ffd08a;font-weight:800;
  padding:1px 5px;border-radius:4px;background:rgba(255,122,26,.13);
  border:1px solid rgba(255,122,26,.25);
}
.cs-sep{width:1px;height:12px;background:rgba(255,255,255,.12);}
.control-strip.fade{opacity:.35;}

/* ============================== HOME ============================== */
.screen{position:absolute;inset:0;z-index:10;}
.home{
  display:flex;flex-direction:column;
  padding:26px 40px 22px;
  background:
    radial-gradient(1200px 640px at 50% 38%,rgba(8,13,24,.2) 0%,rgba(4,7,12,.72) 64%,rgba(2,4,8,.94) 100%);
}
.home-shade{
  position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(180deg,rgba(3,5,10,.82) 0%,rgba(3,5,10,.12) 22%,rgba(3,5,10,0) 44%,rgba(3,5,10,.5) 74%,rgba(3,5,10,.92) 100%),
    radial-gradient(900px 500px at 50% 62%,rgba(255,120,30,.06),transparent 70%);
}
.topbar{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:2;}
.brand-small{display:flex;align-items:center;gap:10px;font-size:10px;letter-spacing:.22em;font-weight:700;color:#c7d5e8;}
.brand-small i{
  font-style:normal;font-size:8px;letter-spacing:.16em;color:var(--gold);
  border:1px solid rgba(255,200,80,.35);background:rgba(255,180,40,.08);
  padding:3px 7px;border-radius:4px;
}
.brand-ball{width:22px;height:22px;color:var(--orange);filter:drop-shadow(0 0 8px rgba(255,122,26,.5));}
.topbar-actions{display:flex;gap:8px;}

.hero{
  position:relative;z-index:2;
  flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding-bottom:8px;
}
.eyebrow{display:flex;align-items:center;gap:16px;margin-bottom:6px;}
.eyebrow span:not(.line){font-size:10px;letter-spacing:.44em;color:#9db2ca;font-weight:700;text-transform:uppercase;}
.eyebrow .line{width:66px;height:1px;background:linear-gradient(90deg,transparent,rgba(255,200,120,.55));}
.eyebrow .line:last-child{background:linear-gradient(90deg,rgba(255,200,120,.55),transparent);}
.wordmark{
  position:relative;
  font-family:var(--font-display);
  font-weight:700;
  font-stretch:condensed;
  font-size:196px;
  line-height:.86;
  letter-spacing:-2px;
  transform:skewX(-6deg);
  background:linear-gradient(180deg,#ffffff 0%,#fff3d6 34%,#ffc35f 50%,#ff8a24 63%,#e2560a 100%);
  -webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent;color:transparent;
  filter:drop-shadow(0 7px 0 rgba(0,0,0,.42)) drop-shadow(0 26px 40px rgba(255,110,20,.24));
  animation:wordIn .9s cubic-bezier(.16,1,.3,1) both, floaty 6s ease-in-out 1s infinite;
}
.wordmark:after{
  content:attr(data-text);
  position:absolute;inset:0;
  background:linear-gradient(180deg,rgba(255,255,255,.9),rgba(255,255,255,0) 30%);
  -webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent;
  opacity:.5;pointer-events:none;
}
.wordmark:before{
  content:"";position:absolute;left:-4%;right:-4%;bottom:-6px;height:14px;
  background:radial-gradient(50% 100% at 50% 0%,rgba(255,150,40,.4),transparent 70%);
  filter:blur(6px);
}
.tagline{
  margin-top:10px;font-family:var(--font-display);
  font-size:19px;letter-spacing:.34em;font-weight:600;color:#c5d4e8;
  text-transform:uppercase;
}
.tagline b{color:var(--gold);font-weight:700;}

.menu{margin-top:34px;display:flex;flex-direction:column;align-items:center;gap:14px;}
.btn{
  position:relative;
  display:inline-flex;align-items:center;justify-content:center;gap:10px;
  transform:skewX(-7deg);
  border:1px solid transparent;
  transition:transform .16s cubic-bezier(.2,1.4,.4,1),filter .16s,background .16s,border-color .16s;
}
.btn>*{transform:skewX(7deg);}
.btn-primary{
  width:392px;height:72px;
  background:linear-gradient(180deg,#ffa742 0%,#ff7a1a 44%,#e85400 100%);
  border-color:rgba(255,210,150,.55);
  border-radius:12px;
  box-shadow:
    0 12px 0 #9c3200,
    0 24px 40px rgba(255,100,10,.34),
    inset 0 1px 0 rgba(255,255,255,.55),
    inset 0 -3px 0 rgba(120,40,0,.35);
  color:#1a0b00;
  overflow:hidden;
}
.btn-primary:hover{
  transform:skewX(-7deg) translateY(-3px);
  filter:brightness(1.06);
  box-shadow:0 15px 0 #9c3200,0 30px 55px rgba(255,110,20,.46),inset 0 1px 0 rgba(255,255,255,.6),inset 0 -3px 0 rgba(120,40,0,.35);
}
.btn-primary:active{transform:skewX(-7deg) translateY(4px);box-shadow:0 6px 0 #9c3200,0 10px 20px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.4);}
.btn-primary .btn-ico{width:24px;height:24px;}
.btn-label{font-family:var(--font-display);font-size:31px;font-weight:700;letter-spacing:1.5px;}
.btn-sub{
  position:absolute;right:14px;top:9px;
  font-size:8px;letter-spacing:.16em;font-weight:800;
  color:rgba(50,20,0,.55);
}
.btn-shine{
  position:absolute;top:-40%;bottom:-40%;width:70px;
  left:-30%;
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.55),transparent);
  transform:skewX(18deg);
  animation:shine 3.6s ease-in-out infinite;
  pointer-events:none;
}
.menu-row{display:flex;gap:12px;}
.btn-ghost{
  height:44px;padding:0 20px;border-radius:9px;
  background:rgba(255,255,255,.045);
  border-color:rgba(255,255,255,.12);
  color:#c8d7ea;
  font-size:11px;font-weight:700;letter-spacing:.16em;
  backdrop-filter:blur(6px);
}
.btn-ghost:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.3);color:#fff;transform:skewX(-7deg) translateY(-2px);}
.btn-ghost:active{transform:skewX(-7deg) translateY(1px);}
.btn-ico-sm{width:15px;height:15px;opacity:.8;}

.home-bottom{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:10px;}
.home-roster{
  width:100%;height:118px;overflow:hidden;position:relative;
  display:flex;gap:10px;
  mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);
  opacity:.72;
}
.home-roster .hr-track{display:flex;gap:10px;animation:marquee 46s linear infinite;will-change:transform;}
.home-roster:hover .hr-track{animation-play-state:paused;}
.hr-card{
  width:94px;height:118px;flex:0 0 94px;border-radius:9px;overflow:hidden;position:relative;
  border:1px solid rgba(255,255,255,.12);
  background:linear-gradient(170deg,#18243a,#080c14);
  box-shadow:0 8px 20px rgba(0,0,0,.45);
  transition:.2s;
}
.hr-card:hover{border-color:rgba(255,180,80,.6);transform:translateY(-4px);}
.hr-card canvas{width:100%;height:100%;display:block;transform:scale(1.5) translateY(4%);}
.hr-card span{
  position:absolute;left:0;right:0;bottom:0;padding:10px 0 4px;
  font-family:var(--font-display);font-size:10px;font-weight:700;letter-spacing:.12em;text-align:center;
  background:linear-gradient(0deg,rgba(3,6,11,.94),transparent);
}
.home-meta{display:flex;align-items:center;gap:12px;font-size:9px;letter-spacing:.2em;color:#7f92a9;font-weight:600;}
.home-meta b{color:#e7eef8;font-weight:800;}
.home-meta i{width:3px;height:3px;border-radius:50%;background:rgba(255,255,255,.25);}
.disclaimer{font-size:8px;letter-spacing:.04em;color:#48566a;text-align:center;max-width:820px;line-height:1.5;}

/* ============================== SELECT ============================== */
.select{
  display:flex;flex-direction:column;
  padding:18px 30px 16px;
  background:
    radial-gradient(1100px 620px at 50% 42%,rgba(9,15,26,.45),rgba(3,6,11,.86) 70%,rgba(2,4,8,.96));
}
.select-shade{position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(180deg,rgba(3,6,11,.72),transparent 20%,transparent 76%,rgba(3,6,11,.75));}
.select-head{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;height:86px;flex:0 0 86px;}
.back-btn{
  display:flex;align-items:center;gap:8px;
  font-size:10px;letter-spacing:.18em;font-weight:700;color:#93a6bc;
  padding:9px 14px;border-radius:8px;border:1px solid rgba(255,255,255,.09);
  background:rgba(255,255,255,.03);transition:.18s;
}
.back-btn svg{width:12px;height:12px;transform:rotate(180deg);}
.back-btn:hover{color:#fff;border-color:rgba(255,255,255,.24);background:rgba(255,255,255,.07);}
.select-title{text-align:center;position:absolute;left:50%;transform:translateX(-50%);}
.eyebrow-mini{display:block;font-size:9px;letter-spacing:.4em;color:var(--gold);font-weight:700;margin-bottom:4px;}
.select-title h2{
  font-family:var(--font-display);font-size:33px;font-weight:600;letter-spacing:.06em;color:#dbe7f7;line-height:1;
}
.select-title h2 b{
  font-weight:700;
  background:linear-gradient(180deg,#fff,#ffc35f 60%,#ff8a24);
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
}
.select-status{display:flex;align-items:center;gap:8px;}
.sel-pill{
  display:flex;align-items:center;gap:7px;padding:7px 11px;border-radius:7px;
  border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.03);
  min-width:132px;
  transition:.2s;
}
.sel-pill span{
  font-size:8px;font-weight:800;letter-spacing:.1em;
  padding:3px 5px;border-radius:3px;background:rgba(255,255,255,.08);
}
.sel-pill b{font-size:10px;font-weight:700;letter-spacing:.08em;color:#93a6bc;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:96px;}
.sel-pill.p1.locked{border-color:rgba(55,217,255,.5);background:rgba(55,217,255,.08);}
.sel-pill.p1.locked span{background:var(--p1);color:#00222c;}
.sel-pill.p1.locked b{color:#c9f6ff;}
.sel-pill.p2.locked{border-color:rgba(255,100,64,.5);background:rgba(255,100,64,.08);}
