.fighter-card.locked.p2{box-shadow:0 24px 70px rgba(0,0,0,.6),0 0 0 1px rgba(255,100,64,.35),0 0 46px rgba(255,100,64,.15);}
.fc-head{display:flex;align-items:center;justify-content:space-between;padding:10px 14px 6px;}
