}
.p1 .fc-glow{background:radial-gradient(circle,rgba(55,217,255,.18),transparent 62%);}
.p2 .fc-glow{background:radial-gradient(circle,rgba(255,100,64,.18),transparent 62%);}
.fc-info{padding:4px 18px 16px;flex:1;display:flex;flex-direction:column;gap:3px;}
.fc-name{font-family:var(--font-display);font-size:29px;font-weight:700;letter-spacing:.02em;line-height:1.02;color:#fff;}
.fc-meta{font-size:9px;letter-spacing:.16em;font-weight:700;color:#7d90a6;}
.fc-nick{font-family:var(--font-display);font-size:13px;letter-spacing:.16em;color:var(--gold);font-weight:600;margin-bottom:8px;}
.p2 .fc-nick{color:#ffb59f;}
.stat-grid{display:flex;flex-direction:column;gap:6px;margin-top:auto;}
.stat-row{display:grid;grid-template-columns:38px 1fr 26px;align-items:center;gap:8px;}
