.stat-bar{height:4px;border-radius:2px;background:rgba(255,255,255,.08);overflow:hidden;}
.stat-bar i{display:block;height:100%;border-radius:2px;background:linear-gradient(90deg,#37d9ff,#7be8ff);transition:width .35s cubic-bezier(.2,1,.3,1);}
.p1 .stat-bar i{background:linear-gradient(90deg,#13b8e0,#7be8ff);}
.p2 .stat-bar i{background:linear-gradient(90deg,#ff4d2e,#ffa27a);}

.roster-wrap{display:flex;flex-direction:column;justify-content:center;gap:14px;min-width:0;}
.roster-grid{
  display:grid;grid-template-columns:repeat(5,1fr);grid-template-rows:repeat(2,1fr);
  gap:12px;
}
.roster-card{
  position:relative;border-radius:11px;overflow:hidden;
  background:linear-gradient(170deg,#141e30 0%,#0a111c 58%,#070b12 100%);
