  transition:transform .18s cubic-bezier(.2,1.3,.4,1),border-color .18s,box-shadow .18s;
  min-height:0;
}
.roster-card:hover{transform:translateY(-3px);border-color:rgba(255,255,255,.26);}
.roster-card canvas{position:absolute;inset:0;width:100%;height:100%;display:block;transform:scale(1.26) translateY(7%);transition:transform .25s;}
.roster-card:hover canvas{transform:scale(1.31) translateY(4%);}
.rc-fade{position:absolute;inset:0;background:linear-gradient(0deg,rgba(3,6,11,.96) 0%,rgba(3,6,11,.4) 30%,transparent 58%);}
.rc-info{position:absolute;left:0;right:0;bottom:0;padding:8px 9px 7px;}
.rc-name{font-family:var(--font-display);font-size:14px;font-weight:700;letter-spacing:.03em;line-height:1;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.rc-sub{margin-top:3px;display:flex;align-items:center;justify-content:space-between;font-size:8px;letter-spacing:.1em;color:#8496ac;font-weight:700;}
.rc-ovr{color:var(--gold);}
.rc-num{
  position:absolute;top:6px;right:7px;
  font-family:var(--font-display);font-size:11px;font-weight:700;
  color:rgba(255,255,255,.5);
}
.rc-badges{position:absolute;top:6px;left:6px;display:flex;gap:3px;}
.rc-badge{
  font-size:8px;font-weight:800;letter-spacing:.06em;
  padding:3px 5px;border-radius:3px;line-height:1;
  opacity:0;transform:translateY(-4px);transition:.16s;
}
.rc-badge.show{opacity:1;transform:none;}
.rc-badge.b1{background:var(--p1);color:#002733;box-shadow:0 0 12px rgba(55,217,255,.5);}
.rc-badge.b2{background:var(--p2);color:#2b0700;box-shadow:0 0 12px rgba(255,100,64,.5);}
.roster-card.active{border-color:rgba(255,255,255,.7);box-shadow:0 0 0 1px rgba(255,255,255,.35),0 12px 30px rgba(0,0,0,.6);transform:translateY(-4px) scale(1.02);}
.roster-card.cur1{border-color:rgba(55,217,255,.75);box-shadow:0 0 0 1px rgba(55,217,255,.3),0 0 26px rgba(55,217,255,.22);}
.roster-card.cur2{border-color:rgba(255,100,64,.75);box-shadow:0 0 0 1px rgba(255,100,64,.3),0 0 26px rgba(255,100,64,.22);}
.roster-card.locked1:after,.roster-card.locked2:after{
  content:"";position:absolute;inset:0;border-radius:11px;pointer-events:none;
}
.roster-card.locked1:after{border:2px solid var(--p1);box-shadow:inset 0 0 26px rgba(55,217,255,.25);}
.roster-card.locked2:after{border:2px solid var(--p2);box-shadow:inset 0 0 26px rgba(255,100,64,.25);}
.roster-hint{display:flex;justify-content:space-between;padding:0 4px;font-size:9px;letter-spacing:.12em;color:#66788e;font-weight:600;}
