/* ============================================================
   AIRBALL — utils: math, colour, canvas helpers
   ============================================================ */
(function(){
  const AB = window.AB = window.AB || {};
  const U = AB.U = {};

  U.TAU = Math.PI * 2;
  U.clamp = (v, a, b) => v < a ? a : (v > b ? b : v);
  U.lerp = (a, b, t) => a + (b - a) * t;
  U.invLerp = (a, b, v) => (v - a) / (b - a || 1);
  U.sat = v => v < 0 ? 0 : v > 1 ? 1 : v;
  U.smoothstep = t => { t = U.sat(t); return t * t * (3 - 2 * t); };
  U.smootherstep = t => { t = U.sat(t); return t * t * t * (t * (t * 6 - 15) + 10); };
  U.damp = (a, b, rate, dt) => a + (b - a) * (1 - Math.exp(-rate * dt));
  U.rand = (a = 1, b = 0) => b + Math.random() * (a - b);
  U.randInt = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
  U.pick = arr => arr[Math.floor(Math.random() * arr.length)];
  U.chance = p => Math.random() < p;
  U.sign = v => v < 0 ? -1 : 1;
  U.dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  U.wrap = (v, n) => ((v % n) + n) % n;
  U.deg = d => d * Math.PI / 180;
  U.easeOutCubic = t => 1 - Math.pow(1 - t, 3);
  U.easeInCubic = t => t * t * t;
  U.easeInOutCubic = t => t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  U.easeOutQuint = t => 1 - Math.pow(1 - t, 5);
  U.easeOutBack = t => { const c = 1.9; return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2); };
  U.easeOutElastic = t => t === 0 ? 0 : t === 1 ? 1 : Math.pow(2, -9 * t) * Math.sin((t * 10 - .75) * (U.TAU / 3)) + 1;
  U.approach = (cur, target, step) => {
    if (cur < target) return Math.min(cur + step, target);
    return Math.max(cur - step, target);
  };

  U.formatClock = s => {
    s = Math.max(0, s);
    const m = Math.floor(s / 60);
    const ss = Math.floor(s % 60);
    if (s < 10 && s > 0) return '0:0' + s.toFixed(1).replace('.', ':').slice(0, 3);
    return m + ':' + String(ss).padStart(2, '0');
  };
  U.formatClockShort = s => {
    const m = Math.floor(Math.max(0, s) / 60);
    const ss = Math.ceil(Math.max(0, s) % 60);
    return m > 0 ? m + ':' + String(Math.min(59, ss)).padStart(2, '0') : '0:' + String(Math.max(0, ss)).padStart(2, '0');
  };

  /* ---------------- seeded rng ---------------- */
  U.rng = function(seed){
    let a = seed >>> 0;
    return function(){
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  };

  /* ---------------- colour ---------------- */
  U.hex2rgb = function(hex){
    if (Array.isArray(hex)) return hex;
    let h = hex.replace('#', '');
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    const n = parseInt(h, 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  U.rgba = function(hex, a){
    const c = U.hex2rgb(hex);
    return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
  };
  U.mix = function(a, b, t){
    const A = U.hex2rgb(a), B = U.hex2rgb(b);
    return `rgb(${Math.round(U.lerp(A[0],B[0],t))},${Math.round(U.lerp(A[1],B[1],t))},${Math.round(U.lerp(A[2],B[2],t))})`;
  };
  U.mixA = function(a, b, t){
    const A = U.hex2rgb(a), B = U.hex2rgb(b);
    return [Math.round(U.lerp(A[0],B[0],t)), Math.round(U.lerp(A[1],B[1],t)), Math.round(U.lerp(A[2],B[2],t))];
  };
  U.shade = function(hex, amt){ // amt -1..1
    const c = U.hex2rgb(hex);
    const t = amt < 0 ? 0 : 255;
    const p = Math.abs(amt);
    return `rgb(${Math.round(U.lerp(c[0],t,p))},${Math.round(U.lerp(c[1],t,p))},${Math.round(U.lerp(c[2],t,p))})`;
  };
  U.lighten = (hex, p) => U.shade(hex, p);
  U.darken = (hex, p) => U.shade(hex, -p);
  U.lum = function(hex){
    const c = U.hex2rgb(hex);
    return (0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2]) / 255;
  };
  U.rgbStr = c => `rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;

  /* ---------------- canvas ---------------- */
  U.mkCanvas = function(w, h){
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.ceil(w));
    c.height = Math.max(1, Math.ceil(h));
    return c;
  };

  U.roundRect = function(ctx, x, y, w, h, r){
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
    return ctx;
  };

  U.capsule = function(ctx, x1, y1, x2, y2, r1, r2){
    const dx = x2 - x1, dy = y2 - y1;
    const d = Math.hypot(dx, dy) || 0.001;
    const ang = Math.atan2(dy, dx);
    const nx = -Math.sin(ang), ny = Math.cos(ang);
    ctx.beginPath();
    ctx.moveTo(x1 + nx * r1, y1 + ny * r1);
    ctx.lineTo(x2 + nx * r2, y2 + ny * r2);
    ctx.arc(x2, y2, r2, ang + Math.PI / 2, ang - Math.PI / 2, true);
    ctx.lineTo(x1 - nx * r1, y1 - ny * r1);
    ctx.arc(x1, y1, r1, ang - Math.PI / 2, ang + Math.PI / 2, true);
    ctx.closePath();
  };

  U.ellipse = function(ctx, x, y, rx, ry){
    ctx.beginPath();
    ctx.ellipse(x, y, Math.max(.01, rx), Math.max(.01, ry), 0, 0, U.TAU);
  };

  U.poly = function(ctx, pts, close = true){
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    if (close) ctx.closePath();
  };

  U.linGrad = function(ctx, x0, y0, x1, y1, stops){
    const g = ctx.createLinearGradient(x0, y0, x1, y1);
    for (const s of stops) g.addColorStop(s[0], s[1]);
    return g;
  };
  U.radGrad = function(ctx, x0, y0, r0, x1, y1, r1, stops){
    const g = ctx.createRadialGradient(x0, y0, r0, x1, y1, r1);
    for (const s of stops) g.addColorStop(s[0], s[1]);
    return g;
  };

  U.glow = function(ctx, x, y, r, color, alpha = 1){
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, U.rgba(color, 0.55 * alpha));
    g.addColorStop(0.4, U.rgba(color, 0.2 * alpha));
    g.addColorStop(1, U.rgba(color, 0));
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  };

  U.text = function(ctx, str, x, y, opt = {}){
    ctx.save();
    const size = opt.size || 16;
    const weight = opt.weight || 600;
    const fam = opt.font || '"Bahnschrift","Arial Narrow",sans-serif';
    ctx.font = `${opt.style || ''} ${weight} ${size}px ${fam}`.trim();
    ctx.textAlign = opt.align || 'center';
    ctx.textBaseline = opt.baseline || 'middle';
    if (opt.alpha != null) ctx.globalAlpha *= opt.alpha;
    if (opt.shadow) { ctx.shadowColor = opt.shadow; ctx.shadowBlur = opt.blur || 12; ctx.shadowOffsetY = opt.shadowY || 0; }
    if (opt.spacing != null && 'letterSpacing' in ctx) ctx.letterSpacing = opt.spacing + 'px';
    ctx.fillStyle = opt.color || '#fff';
    ctx.fillText(str, x, y);
    ctx.restore();
  };

  U.measureSpaced = function(ctx, str, spacing){
    let w = 0;
    for (const ch of str) w += ctx.measureText(ch).width + spacing;
    return w - spacing;
  };

  U.drawSpaced = function(ctx, str, x, y, spacing, opt = {}){
    const align = opt.align || 'center';
    ctx.save();
    ctx.font = `${opt.weight || 600} ${opt.size || 16}px ${opt.font || '"Bahnschrift","Arial Narrow",sans-serif'}`;
    ctx.textBaseline = opt.baseline || 'middle';
    ctx.fillStyle = opt.color || '#fff';
    if (opt.alpha != null) ctx.globalAlpha *= opt.alpha;
    if (opt.shadow) { ctx.shadowColor = opt.shadow; ctx.shadowBlur = opt.blur || 10; }
    const total = U.measureSpaced(ctx, str, spacing);
    let cx = align === 'center' ? x - total / 2 : align === 'right' ? x - total : x;
    for (const ch of str) {
      ctx.fillText(ch, cx, y);
      cx += ctx.measureText(ch).width + spacing;
    }
    ctx.restore();
  };

  U.star = function(ctx, x, y, r1, r2, points, rot = 0){
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 ? r2 : r1;
      const a = rot + i * Math.PI / points - Math.PI / 2;
      const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
      i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
    }
    ctx.closePath();
  };

  U.lerpAngle = function(a, b, t){
    let d = ((b - a + Math.PI) % U.TAU) - Math.PI;
    if (d < -Math.PI) d += U.TAU;
    return a + d * t;
  };

  U.shuffle = function(arr){
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
})();

/* ============================================================
   AIRBALL — procedural audio (no samples)
   ============================================================ */
(function(){
  const AB = window.AB = window.AB || {};

  const Audio = AB.Audio = {
    ctx: null,
    master: null,
    sfxBus: null,
    crowdBus: null,
    noiseBuf: null,
    started: false,
    muted: false,
    volume: 0.8,
    crowdLevel: 0,
    _crowdNodes: null,

    unlock(){
      if (this.started) {
        if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
        return;
      }
      try {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return;
        const ctx = this.ctx = new AC();
        this.master = ctx.createGain();
        this.master.gain.value = this.muted ? 0 : this.volume;
        this.master.connect(ctx.destination);

        this.sfxBus = ctx.createGain();
        this.sfxBus.gain.value = 0.9;
        this.sfxBus.connect(this.master);

        this.crowdBus = ctx.createGain();
        this.crowdBus.gain.value = 0.55;
        this.crowdBus.connect(this.master);

        // noise buffer
        const len = Math.floor(ctx.sampleRate * 2.2);
        const buf = ctx.createBuffer(1, len, ctx.sampleRate);
        const d = buf.getChannelData(0);
        let last = 0;
        for (let i = 0; i < len; i++){
          const white = Math.random() * 2 - 1;
          last = (last + 0.02 * white) / 1.02;
          d[i] = last * 3.2 + white * 0.25;
        }
        this.noiseBuf = buf;
        this.started = true;
        this._crowd();
      } catch (e) { /* audio is a luxury */ }
    },

    setMuted(m){
      this.muted = !!m;
      if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, 0.03);
    },

    _now(){ return this.ctx ? this.ctx.currentTime : 0; },

    _noise(opt){
      if (!this.started || this.muted) return;
      const ctx = this.ctx, t = this._now() + (opt.delay || 0);
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      src.playbackRate.value = opt.rate || 1;
      const f = ctx.createBiquadFilter();
      f.type = opt.filter || 'bandpass';
      f.frequency.setValueAtTime(opt.freq || 1000, t);
      if (opt.to) f.frequency.exponentialRampToValueAtTime(Math.max(40, opt.to), t + (opt.dur || 0.3));
      f.Q.value = opt.q != null ? opt.q : 1;
      const g = ctx.createGain();
      const vol = (opt.gain != null ? opt.gain : 0.2);
      const atk = opt.attack || 0.004;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + atk);
      g.gain.exponentialRampToValueAtTime(0.0001, t + (opt.dur || 0.3));
      const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
      if (pan) pan.pan.value = AB.U.clamp(opt.pan || 0, -1, 1);
      src.connect(f); f.connect(g);
      if (pan) { g.connect(pan); pan.connect(opt.bus || this.sfxBus); }
      else g.connect(opt.bus || this.sfxBus);
      src.start(t);
      src.stop(t + (opt.dur || 0.3) + 0.05);
    },

    _tone(opt){
      if (!this.started || this.muted) return;
      const ctx = this.ctx, t = this._now() + (opt.delay || 0);
      const o = ctx.createOscillator();
      o.type = opt.type || 'sine';
      o.frequency.setValueAtTime(opt.freq, t);
      if (opt.to) o.frequency.exponentialRampToValueAtTime(Math.max(20, opt.to), t + (opt.dur || .3));
      const g = ctx.createGain();
      const vol = opt.gain != null ? opt.gain : 0.15;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(Math.max(0.0003, vol), t + (opt.attack || 0.005));
      g.gain.exponentialRampToValueAtTime(0.0001, t + (opt.dur || .3));
      const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
      if (pan) pan.pan.value = AB.U.clamp(opt.pan || 0, -1, 1);
      o.connect(g);
      if (pan) { g.connect(pan); pan.connect(this.sfxBus); }
      else g.connect(this.sfxBus);
      o.start(t); o.stop(t + (opt.dur || .3) + 0.05);
    },

    /* ---------------- ambience ---------------- */
    _crowd(){
      if (!this.started) return;
      const ctx = this.ctx;
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      src.loop = true;
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass'; f.frequency.value = 520; f.Q.value = 0.55;
      const f2 = ctx.createBiquadFilter();
      f2.type = 'lowpass'; f2.frequency.value = 2100;
      const g = ctx.createGain();
      g.gain.value = 0.05;
      src.connect(f); f.connect(f2); f2.connect(g); g.connect(this.crowdBus);
      src.start();
      this._crowdNodes = { src, g, f };
      this._ambientTimer = setInterval(() => {
        if (!this.ctx || this.muted) return;
        const lvl = 0.04 + this.crowdLevel * 0.1;
        g.gain.setTargetAtTime(lvl, this.ctx.currentTime, 1.2);
      }, 1400);
    },

    crowd(level){
      this.crowdLevel = AB.U.clamp(level, 0, 1);
      if (this._crowdNodes && this.ctx && !this.muted){
        this._crowdNodes.g.gain.setTargetAtTime(0.038 + this.crowdLevel * 0.11, this.ctx.currentTime, 0.6);
      }
    },

    roar(intensity = 0.6, pan = 0){
      if (!this.started || this.muted) return;
      const i = AB.U.clamp(intensity, 0, 1);
      this._noise({ dur: 1.5, gain: 0.12 + i * 0.22, freq: 300, to: 700, q: 0.5, attack: 0.09, filter:'bandpass', pan });
      this._noise({ dur: 1.15, gain: 0.05 + i * 0.15, freq: 1600, to: 900, q: 0.7, attack: 0.06, filter:'bandpass', pan });
      this._noise({ dur: 0.7, gain: 0.1 + i * 0.18, freq: 2400, to: 1400, q: 0.9, attack: 0.03, pan });
    },

    /* ---------------- sfx ---------------- */
    dribble(power = 1, pan = 0){
      this._tone({ freq: 128, to: 56, type: 'sine', dur: 0.13, gain: 0.06 + power * 0.07, pan });
      this._noise({ dur: 0.05, freq: 320, to: 140, gain: 0.03 * power, filter: 'lowpass', pan });
    },

    bounce(power = 1, pan = 0){
      this._tone({ freq: 96, to: 48, type: 'sine', dur: 0.18, gain: 0.09 * power, pan });
      this._noise({ dur: 0.07, freq: 260, to: 120, gain: 0.05 * power, filter: 'lowpass', pan });
    },

    grab(pan = 0){
      this._noise({ dur: 0.06, freq: 900, to: 380, gain: 0.07, q: 1.4, pan });
      this._tone({ freq: 180, to: 120, type: 'sine', dur: 0.07, gain: 0.05, pan });
    },

    swish(pan = 0){
      this._noise({ dur: 0.32, freq: 1500, to: 5200, gain: 0.11, q: 1.4, attack: 0.02, filter: 'bandpass', pan });
      this._noise({ dur: 0.2, freq: 600, to: 1500, gain: 0.05, q: 0.8, attack: 0.005, pan });
      this._tone({ freq: 2300, to: 1500, type: 'sine', dur: 0.1, gain: 0.025, pan });
    },

    rim(pan = 0){
      this._tone({ freq: 780, to: 620, type: 'triangle', dur: 0.28, gain: 0.08, pan });
      this._tone({ freq: 1420, to: 1200, type: 'sine', dur: 0.2, gain: 0.045, pan });
      this._noise({ dur: 0.09, freq: 2400, to: 1200, gain: 0.04, q: 2.2, pan });
    },

    glass(pan = 0){
      this._tone({ freq: 190, to: 110, type: 'sine', dur: 0.16, gain: 0.08, pan });
      this._noise({ dur: 0.12, freq: 1200, to: 400, gain: 0.05, q: 1.1, pan });
    },

    jump(pan = 0){
      this._noise({ dur: 0.14, freq: 700, to: 1700, gain: 0.03, q: 0.9, attack: 0.01, pan });
    },

    land(pan = 0, power = 1){
      this._tone({ freq: 110, to: 52, type: 'sine', dur: 0.16, gain: 0.07 * power, pan });
      this._noise({ dur: 0.1, freq: 500, to: 180, gain: 0.04 * power, filter:'lowpass', pan });
    },

    steal(pan = 0){
      this._noise({ dur: 0.11, freq: 2100, to: 700, gain: 0.1, q: 1.2, pan });
      this._tone({ freq: 320, to: 160, type: 'square', dur: 0.07, gain: 0.035, pan });
    },

    block(pan = 0){
      this._noise({ dur: 0.16, freq: 1400, to: 260, gain: 0.14, q: 0.9, pan });
      this._tone({ freq: 200, to: 70, type: 'sine', dur: 0.22, gain: 0.12, pan });
    },

    dunk(pan = 0){
      this._tone({ freq: 90, to: 32, type: 'sine', dur: 0.5, gain: 0.3, pan });
      this._noise({ dur: 0.4, freq: 500, to: 90, gain: 0.2, filter: 'lowpass', q: 0.7, pan });
      this._tone({ freq: 1400, to: 700, type: 'triangle', dur: 0.3, gain: 0.07, pan, delay: 0.02 });
      this.roar(0.95, pan);
    },

    whistle(){
      this._tone({ freq: 2400, to: 2500, type: 'sine', dur: 0.28, gain: 0.06 });
      this._tone({ freq: 3150, to: 3050, type: 'sine', dur: 0.26, gain: 0.04, delay: 0.02 });
    },

    buzzer(){
      this._tone({ freq: 220, to: 210, type: 'square', dur: 0.85, gain: 0.06 });
      this._tone({ freq: 110, to: 108, type: 'sawtooth', dur: 0.9, gain: 0.035 });
      this._noise({ dur: 0.6, freq: 1200, to: 600, gain: 0.04, filter:'bandpass', q: 1.4 });
    },

    beep(high = false){
      this._tone({ freq: high ? 1180 : 760, type: 'sine', dur: 0.16, gain: 0.075 });
      this._tone({ freq: high ? 590 : 380, type: 'triangle', dur: 0.14, gain: 0.03 });
    },

    tick(){
      this._tone({ freq: 1600, type: 'sine', dur: 0.045, gain: 0.022 });
    },

    ui(){
      this._tone({ freq: 640, to: 880, type: 'sine', dur: 0.08, gain: 0.045 });
      this._noise({ dur: 0.03, freq: 2600, to: 1800, gain: 0.012, q: 2 });
    },

    uiBack(){
      this._tone({ freq: 520, to: 300, type: 'sine', dur: 0.1, gain: 0.04 });
    },

    lock(){
      this._tone({ freq: 420, to: 840, type: 'triangle', dur: 0.18, gain: 0.07 });
      this._tone({ freq: 1260, type: 'sine', dur: 0.16, gain: 0.04, delay: 0.07 });
    },

    fire(){
      this._noise({ dur: 0.9, freq: 300, to: 1500, gain: 0.07, q: 0.8, attack: 0.1 });
      this._tone({ freq: 130, to: 260, type: 'sawtooth', dur: 0.7, gain: 0.03 });
      this.roar(0.7);
    }
  };
})();

/* ============================================================
   AIRBALL — arena / court / hoop / ball art
   All artwork is hand-built with canvas vectors.
   ============================================================ */
(function(){
  const AB = window.AB = window.AB || {};
  const U = AB.U, C = AB.C;
  const W = C.W, H = C.H;

  const Art = AB.Art = {
    arena: null,
    court: null,
    seats: [],
    theme: null,

    defaultTheme(){
      const a = AB.byId('curry'), b = AB.byId('jordan');
      return {
        a: { primary:a.colors.primary, secondary:a.colors.secondary, jersey:a.colors.jersey, trim:a.colors.trim },
        b: { primary:b.colors.primary, secondary:b.colors.secondary, jersey:b.colors.jersey, trim:b.colors.trim },
        p1: a, p2: b, label1: 'CURRY', label2: 'JORDAN'
      };
    },

    init(theme){
      if (!theme) theme = this.defaultTheme();
      this.theme = theme;
      this.buildArena(theme);
      this.buildCourt(theme);
    },

    /* ============================================================
       ARENA
       ============================================================ */
    buildArena(theme){
      const cv = U.mkCanvas(W, H);
      const g = cv.getContext('2d');
      const rand = U.rng(9137);
      this.seats = [];

      /* ---- base ceiling / room ---- */
      let grd = g.createLinearGradient(0, 0, 0, H);
      grd.addColorStop(0, '#04060b');
      grd.addColorStop(.26, '#070b13');
      grd.addColorStop(.62, '#0a1019');
      grd.addColorStop(1, '#05080e');
      g.fillStyle = grd; g.fillRect(0, 0, W, H);

      /* ---- roof trusses ---- */
      g.strokeStyle = 'rgba(120,145,180,.07)';
      g.lineWidth = 2;
      for (let i = 0; i < 3; i++){
        const y = 26 + i * 26;
        g.beginPath();
        g.moveTo(0, y + 12); g.lineTo(W, y - 6);
        g.stroke();
      }
      g.lineWidth = 1;
      g.strokeStyle = 'rgba(120,145,180,.045)';
      for (let x = -40; x < W + 80; x += 92){
        g.beginPath();
        g.moveTo(x, 8); g.lineTo(x + 52, 84);
        g.moveTo(x + 52, 84); g.lineTo(x + 104, 8);
        g.stroke();
      }
      // lamps in the rafters
      for (let i = 0; i < 8; i++){
        const x = 90 + i * 205, y = 62;
        U.glow(g, x, y, 46, '#9fc7ff', .16);
        g.fillStyle = 'rgba(210,230,255,.55)';
        g.fillRect(x - 8, y - 2, 16, 4);
      }

      /* ---- upper deck crowd ---- */
      this.crowdTier(g, rand, 104, 292, 7, 10, 0.86, [40, 300, 560, 820, 1080, 1340, 1560]);
      // walkway / balcony
      g.fillStyle = '#05080e'; g.fillRect(0, 292, W, 34);
      g.fillStyle = 'rgba(255,255,255,.06)'; g.fillRect(0, 292, W, 1.5);
      g.fillStyle = 'rgba(255,255,255,.035)'; g.fillRect(0, 324, W, 1.5);
      for (let x = 0; x < W; x += 74){
        g.fillStyle = 'rgba(140,165,200,.05)';
        g.fillRect(x, 296, 1, 28);
      }
      // luxury box strip
      for (let i = 0; i < 10; i++){
        const x = 24 + i * 158;
        g.fillStyle = 'rgba(130,150,185,.05)';
        g.fillRect(x, 304, 118, 14);
        g.fillStyle = 'rgba(200,225,255,.07)';
        g.fillRect(x, 304, 118, 1);
        U.glow(g, x + 59, 311, 30, '#ffd28a', .05);
      }

      /* ---- lower bowl crowd ---- */
      this.crowdTier(g, rand, 330, 500, 8, 11, 1, [40, 250, 470, 700, 930, 1160, 1390, 1560]);

      // tunnels
      this.tunnel(g, 300, 356, 62, 144, theme.a.primary);
      this.tunnel(g, 1300, 356, 62, 144, theme.b.primary);

      // lower railing
      g.fillStyle = '#04070c'; g.fillRect(0, 500, W, 16);
      g.fillStyle = 'rgba(255,255,255,.06)'; g.fillRect(0, 500, W, 1.5);

      /* ---- banners hanging in the rafters ---- */
      const banners = [
        { x: 402, c: '#CE1141', c2:'#1a0409', n:'6' },
        { x: 486, c: '#1D428A', c2:'#0a0f24', n:'3' },
        { x: 1114, c: '#552583', c2:'#140a24', n:'17' },
        { x: 1198, c: '#0E2240', c2:'#060c16', n:'1' }
      ];
      for (const b of banners) this.banner(g, b.x, 76, 44, 156, b.c, b.c2, b.n);

      /* ---- courtside concourse wall ---- */
      grd = g.createLinearGradient(0, 516, 0, 706);
      grd.addColorStop(0, '#070b12');
      grd.addColorStop(.55, '#0a0f18');
      grd.addColorStop(1, '#05080d');
      g.fillStyle = grd; g.fillRect(0, 516, W, 190);

      // huge ghost wordmark on the wall
      g.save();
      g.globalAlpha = .055;
      g.font = '700 120px "Bahnschrift","Arial Narrow",sans-serif';
      g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillStyle = '#dfe9ff';
      g.fillText('AIRBALL', 800, 606);
      g.restore();

      // wall panel seams + subtle uplights in team colours
      for (let x = 0; x < W; x += 160){
        g.fillStyle = 'rgba(255,255,255,.022)';
        g.fillRect(x, 516, 1, 190);
      }
      for (let i = 0; i < 8; i++){
        const x = 100 + i * 200;
        const col = i % 2 ? theme.b.primary : theme.a.primary;
        U.glow(g, x, 690, 90, col, .07);
      }

      // courtside spectators silhouettes
      this.courtside(g, rand, theme);

      // baseline LED strip
      g.fillStyle = '#020407';
      g.fillRect(0, 690, W, 18);
      g.fillStyle = 'rgba(255,255,255,.05)';
      g.fillRect(0, 690, W, 1);
      g.fillStyle = 'rgba(0,0,0,.4)';
      g.fillRect(0, 705, W, 4);

      // global dim / vignette baked into arena
      grd = g.createRadialGradient(800, 430, 180, 800, 470, 1000);
      grd.addColorStop(0, 'rgba(0,0,0,0)');
      grd.addColorStop(.55, 'rgba(0,0,0,.16)');
      grd.addColorStop(1, 'rgba(0,0,0,.62)');
      g.fillStyle = grd; g.fillRect(0, 0, W, H);

      // atmosphere haze
      const hz = g.createLinearGradient(0, 240, 0, 620);
      hz.addColorStop(0, 'rgba(70,110,190,.055)');
      hz.addColorStop(.5, 'rgba(40,70,130,.03)');
      hz.addColorStop(1, 'rgba(0,0,0,0)');
      g.fillStyle = hz; g.fillRect(0, 240, W, 380);

      this.arena = cv;
    },

    crowdTier(g, rand, y0, y1, rows, rowH, bright, aisles){
      const cols = ['#1b2537','#232c3c','#2b2a33','#1d3341','#33262b','#26343a','#3a2f30','#1a2430','#2f3a48','#262130'];
      const skins = ['#6b4a34','#8a6246','#a67a58','#5b3c2a','#c0916d'];
      const accents = ['#8b1f2c','#946b1e','#1f4d6b','#2b5c33','#5a2a63','#8a4520'];
      for (let r = 0; r < rows; r++){
        const y = y0 + r * rowH;
        const dim = 0.35 + 0.5 * (r / rows);
        const cells = 210;
        for (let i = 0; i < cells; i++){
          const x = 4 + i * (W / cells) + rand() * 5;
          let skip = false;
          for (const a of aisles){
            if (Math.abs(x - a) < 17) { skip = true; break; }
          }
          if (skip) continue;
          const roll = rand();
          let col;
          if (roll < 0.055) col = skins[(rand() * skins.length) | 0];
          else if (roll < 0.085) col = accents[(rand() * accents.length) | 0];
          else col = cols[(rand() * cols.length) | 0];
          g.globalAlpha = dim * (0.55 + rand() * 0.45) * bright;
          g.fillStyle = col;
          const hh = 3 + rand() * 2.4;
          g.fillRect(x, y + rand() * 3, 2.6 + rand() * 1.6, hh);
          // tiny head
          if (rand() < .5){
            g.fillStyle = rand() < .5 ? '#c89a72' : '#6b4a34';
            g.globalAlpha = dim * .5;
            g.fillRect(x + .4, y + (rand() * 2), 3.2, 2.4);
          }
          if (rand() < .012){
            this.seats.push({ x, y: y + 2 });
          }
        }
      }
      g.globalAlpha = 1;
      // tier shadow gradient
      const sh = g.createLinearGradient(0, y0 - 8, 0, y1 + 6);
      sh.addColorStop(0, 'rgba(2,4,8,.72)');
      sh.addColorStop(.35, 'rgba(2,4,8,.06)');
      sh.addColorStop(1, 'rgba(2,4,8,.55)');
      g.fillStyle = sh;
      g.fillRect(0, y0 - 8, W, y1 - y0 + 14);
    },

    tunnel(g, x, y, w, h, col){
      const grd = g.createLinearGradient(0, y, 0, y + h);
      grd.addColorStop(0, '#010204');
      grd.addColorStop(1, '#070b12');
      g.fillStyle = grd;
      U.roundRect(g, x - w / 2, y, w, h, 26);
      g.fill();
      g.strokeStyle = 'rgba(210,230,255,.09)';
      g.lineWidth = 2; g.stroke();
      const gl = g.createLinearGradient(x, y, x, y + h);
      gl.addColorStop(0, U.rgba(col, .12));
      gl.addColorStop(1, 'rgba(0,0,0,0)');
      g.fillStyle = gl;
      U.roundRect(g, x - w / 2 + 4, y + 4, w - 8, h - 8, 22);
      g.fill();
      U.glow(g, x, y + h - 10, 70, col, .16);
    },

    banner(g, x, y, w, h, col, dark, num){
      g.save();
      g.strokeStyle = 'rgba(180,200,230,.12)';
      g.lineWidth = 1;
      g.beginPath(); g.moveTo(x + w / 2, 0); g.lineTo(x + w / 2, y); g.stroke();
      const grd = g.createLinearGradient(x, y, x + w, y + h);
      grd.addColorStop(0, U.darken(col, .18));
      grd.addColorStop(.5, col);
      grd.addColorStop(1, U.darken(col, .38));
      g.fillStyle = grd;
      U.poly(g, [[x, y], [x + w, y], [x + w, y + h - 16], [x + w / 2, y + h], [x, y + h - 16]]);
      g.fill();
      g.strokeStyle = 'rgba(255,255,255,.13)'; g.lineWidth = 1.4; g.stroke();
      g.strokeStyle = 'rgba(255,255,255,.22)';
      g.strokeRect(x + 5, y + 6, w - 10, h - 26);
      g.fillStyle = 'rgba(255,255,255,.82)';
      g.font = '700 18px "Bahnschrift","Arial Narrow",sans-serif';
      g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillText(num, x + w / 2, y + 34);
      g.fillStyle = 'rgba(255,255,255,.5)';
      g.font = '600 6px "Segoe UI",sans-serif';
      g.fillText('AIRBALL', x + w / 2, y + h - 38);
      g.restore();
    },

    courtside(g, rand, theme){
      // seated silhouettes with rim light
      for (let i = 0; i < 46; i++){
        const x = 10 + rand() * (W - 20);
        if (x > 690 && x < 910) continue;
        const s = .8 + rand() * .55;
        const y = 690 - 20 * s;
        const col = i % 5 === 0 ? U.mixA('#05080d', theme.a.primary, .18) : [6, 8, 13];
        g.fillStyle = U.rgbStr(col);
        // shoulders
        g.beginPath();
        g.ellipse(x, y + 10 * s, 15 * s, 11 * s, 0, Math.PI, U.TAU);
        g.fill();
        // head
        g.beginPath();
        g.arc(x, y - 4 * s, 6.4 * s, 0, U.TAU);
        g.fill();
        // rim light
        g.strokeStyle = 'rgba(190,215,255,.14)';
        g.lineWidth = 1;
        g.beginPath();
        g.arc(x, y - 4 * s, 6.4 * s, -2.5, -1.1);
        g.stroke();
      }
      // photographers kneeling at the baseline
      for (const x of [420, 760, 1010, 1240]){
        g.fillStyle = '#03050a';
        g.beginPath();
        g.ellipse(x, 694, 17, 9, 0, Math.PI, U.TAU);
        g.fill();
        g.beginPath(); g.arc(x + 9, 683, 5.4, 0, U.TAU); g.fill();
        g.fillStyle = 'rgba(160,190,230,.18)';
        g.fillRect(x + 12, 680, 7, 5);
      }
    },

    /* ============================================================
       COURT
       ============================================================ */
    buildCourt(theme){
      const cv = U.mkCanvas(W, H);
      const g = cv.getContext('2d');
      const rand = U.rng(4412);
      const top = 706, bot = 900;
      const A = theme.a, B = theme.b;

      // hardwood base
      let grd = g.createLinearGradient(0, top, 0, bot);
      grd.addColorStop(0, '#a9703a');
      grd.addColorStop(.3, '#c88a4c');
      grd.addColorStop(.72, '#dba15e');
      grd.addColorStop(1, '#c2864a');
      g.fillStyle = grd;
      g.fillRect(0, top, W, bot - top);

      // planks (horizontal bands with perspective)
      let y = top;
      let row = 0;
      while (y < bot){
        const hgt = 15 + (y - top) * 0.028;
        const tone = 0.02 + (row % 4) * 0.012 + rand() * .03;
        g.fillStyle = row % 2 ? `rgba(255,225,180,${tone})` : `rgba(70,35,10,${tone})`;
        g.fillRect(0, y, W, hgt);
        g.fillStyle = 'rgba(60,30,8,.13)';
        g.fillRect(0, y + hgt - 1, W, 1);
        // grain
        for (let i = 0; i < 26; i++){
          const gx = rand() * W, gw = 30 + rand() * 200;
          g.fillStyle = `rgba(80,42,12,${.02 + rand() * .035})`;
          g.fillRect(gx, y + 3 + rand() * (hgt - 5), gw, .8);
        }
        y += hgt; row++;
      }
      // plank joints
      for (let x = -40; x < W + 40; x += 84){
        g.fillStyle = 'rgba(60,30,8,.1)';
        g.fillRect(x + rand() * 30, top, 1, bot - top);
      }

      // lane paint (dunk zone)
      this.paintLane(g, theme.a, true);
      this.paintLane(g, theme.b, false);

      // centre court + logo
      g.save();
      g.globalAlpha = .9;
      g.strokeStyle = 'rgba(255,240,215,.62)';
      g.lineWidth = 3;
      g.beginPath();
      g.ellipse(800, 818, 168, 66, 0, 0, U.TAU);
      g.stroke();
      g.lineWidth = 1.5;
      g.globalAlpha = .38;
      g.beginPath();
      g.ellipse(800, 818, 138, 52, 0, 0, U.TAU);
      g.stroke();
      g.restore();

      // centre wordmark on the floor
      g.save();
      g.translate(800, 820);
      g.scale(1, .4);
      g.globalAlpha = .33;
      g.fillStyle = '#fff3dd';
      g.font = '700 58px "Bahnschrift","Arial Narrow",sans-serif';
      g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillText('AIRBALL', 0, -22);
      g.font = '600 18px "Bahnschrift","Arial Narrow",sans-serif';
      g.globalAlpha = .26;
      g.fillText('A R E N A', 0, 32);
      g.restore();

      // half court line
      g.strokeStyle = 'rgba(255,240,215,.42)';
      g.lineWidth = 2.5;
      g.beginPath();
      g.moveTo(800, top + 4);
      g.lineTo(800, bot);
      g.stroke();

      // 3pt arcs
      this.threeLine(g, C.RIM_L, 1);
      this.threeLine(g, C.RIM_R, -1);

      // sidelines
      g.strokeStyle = 'rgba(255,240,215,.34)';
      g.lineWidth = 3;
      g.beginPath(); g.moveTo(0, top + 2.5); g.lineTo(W, top + 2.5); g.stroke();
      g.lineWidth = 4;
      g.beginPath(); g.moveTo(0, bot - 2); g.lineTo(W, bot - 2); g.stroke();

      // baseline edge glow
      const bl = g.createLinearGradient(0, top, 0, top + 22);
      bl.addColorStop(0, 'rgba(255,220,150,.16)');
      bl.addColorStop(1, 'rgba(255,220,150,0)');
      g.fillStyle = bl; g.fillRect(0, top, W, 22);

      // glossy sheen
      grd = g.createLinearGradient(0, top, 0, bot);
      grd.addColorStop(0, 'rgba(255,255,255,.09)');
      grd.addColorStop(.24, 'rgba(255,255,255,.015)');
      grd.addColorStop(.55, 'rgba(255,255,255,.05)');
      grd.addColorStop(1, 'rgba(255,255,255,.0)');
      g.fillStyle = grd; g.fillRect(0, top, W, bot - top);

      // long soft reflection bands
      g.save();
      g.globalCompositeOperation = 'screen';
      for (let i = 0; i < 5; i++){
        const bx = 120 + i * 330 + rand() * 80;
        const bg = g.createLinearGradient(bx, top, bx + 120, bot);
        bg.addColorStop(0, 'rgba(255,235,200,.045)');
        bg.addColorStop(1, 'rgba(255,235,200,0)');
        g.fillStyle = bg;
        g.fillRect(bx, top, 130, bot - top);
      }
      g.restore();

      // front edge darkening
      grd = g.createLinearGradient(0, bot - 70, 0, bot);
      grd.addColorStop(0, 'rgba(20,10,4,0)');
      grd.addColorStop(1, 'rgba(10,5,2,.55)');
      g.fillStyle = grd; g.fillRect(0, bot - 70, W, 70);

      // baseline text
      g.save();
      g.globalAlpha = .22;
      g.fillStyle = '#fff1d8';
      g.font = '700 13px "Bahnschrift","Arial Narrow",sans-serif';
      g.textAlign = 'center';
      g.fillText('A I R B A L L   A R E N A', 800, 888);
      g.restore();

      this.court = cv;
    },

    paintLane(g, team, left){
      const top = 706, bot = 892;
      const rim = left ? C.RIM_L : C.RIM_R;
      const depth = C.DUNK_DIST;
      const x0 = left ? C.BOARD_L_X : C.BOARD_R_X;
      const x1 = left ? x0 + depth + 46 : x0 - depth - 46;
      const skew = left ? -34 : 34;
      g.save();
      const grd = g.createLinearGradient(0, top, 0, bot);
      grd.addColorStop(0, U.rgba(team.primary, .30));
      grd.addColorStop(.55, U.rgba(team.primary, .22));
      grd.addColorStop(1, U.rgba(team.primary, .32));
      g.fillStyle = grd;
      U.poly(g, [[x0, top], [x1, top], [x1 + skew, bot], [x0 + skew, bot]]);
      g.fill();
      // paint glow at the outer edge
      g.strokeStyle = U.rgba(team.secondary, .5);
      g.lineWidth = 3;
      g.beginPath();
      g.moveTo(x1, top); g.lineTo(x1 + skew, bot);
      g.stroke();
      g.strokeStyle = 'rgba(255,240,215,.5)';
      g.lineWidth = 2;
      U.poly(g, [[x0, top], [x1, top], [x1 + skew, bot], [x0 + skew, bot]]);
      g.stroke();
      // free throw arc
      g.beginPath();
      g.ellipse(left ? x1 + 8 : x1 - 8, 806, 44, 22, 0, 0, U.TAU);
      g.stroke();
      // lane text
      g.save();
      g.translate((x0 + x1) / 2 + 14, 826);
      g.scale(1, .44);
      g.globalAlpha = .34;
      g.fillStyle = team.secondary;
      g.font = '700 22px "Bahnschrift","Arial Narrow",sans-serif';
      g.textAlign = 'center';
      g.fillText('DUNK ZONE', 0, 0);
      g.restore();
      g.restore();
    },

    threeLine(g, rim, dir){
      const top = 706, bot = 890;
      const base = rim + dir * C.THREE_DIST;
      g.save();
      g.strokeStyle = 'rgba(255,240,215,.55)';
      g.lineWidth = 3;
      g.beginPath();
      g.moveTo(base, top);
      g.bezierCurveTo(base + dir * 10, 760, base + dir * 34, 848, base + dir * 26, bot);
      g.stroke();
      // 3 marker
      g.globalAlpha = .4;
      g.fillStyle = '#fff2da';
      g.font = '700 22px "Bahnschrift","Arial Narrow",sans-serif';
      g.textAlign = 'center';
      g.fillText('3', base + dir * 38, 806);
      g.restore();
    },

    /* ============================================================
       dynamic backdrop
       ============================================================ */
    drawBackdrop(ctx, t, theme, opts = {}){
      ctx.drawImage(this.arena, 0, 0);

      /* spotlight beams */
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const beams = [
        { x: 150, a: 0.22 + Math.sin(t * .17) * .07, w: 260 },
        { x: 560, a: 0.16 + Math.sin(t * .13 + 2) * .05, w: 300 },
        { x: 1040, a: 0.17 + Math.sin(t * .15 + 4) * .06, w: 290 },
        { x: 1450, a: 0.21 + Math.sin(t * .11 + 1) * .07, w: 260 }
      ];
      for (const b of beams){
        const topX = b.x, topY = 50;
        const baseX = 800 + (b.x - 800) * .35 + Math.sin(t * .2 + b.x) * 90;
        const spread = b.w;
        const grd = ctx.createLinearGradient(topX, topY, baseX, 780);
        grd.addColorStop(0, 'rgba(180,210,255,.16)');
        grd.addColorStop(.45, 'rgba(150,190,255,.055)');
        grd.addColorStop(1, 'rgba(120,170,255,0)');
        ctx.fillStyle = grd;
        ctx.beginPath();
        ctx.moveTo(topX - 5, topY);
        ctx.lineTo(topX + 5, topY);
        ctx.lineTo(baseX + spread, 800);
        ctx.lineTo(baseX - spread, 800);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();

      /* crowd camera flashes */
      const flashRand = Math.sin(t * 999) * 10000;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const n = 10;
      for (let i = 0; i < n; i++){
        const idx = Math.floor(Math.abs(Math.sin((t * .7 + i * 1.37) * 3.1)) * this.seats.length);
        const s = this.seats[idx % this.seats.length];
        if (!s) continue;
        const pulse = Math.pow(Math.max(0, Math.sin(t * (2 + (i % 3)) + i * 2.1)), 22);
        if (pulse < .05) continue;
        ctx.globalAlpha = pulse * .9;
        U.glow(ctx, s.x, s.y, 22, '#cfe6ff', .8);
        ctx.fillStyle = '#fff';
        ctx.fillRect(s.x - 1, s.y - 1, 2.4, 2.4);
      }
      ctx.restore();

      /* LED ribbon */
      this.ribbon(ctx, t, 512, 44, theme, opts);
    },

    ribbon(ctx, t, y, h, theme, opts){
      // panel
      const grd = ctx.createLinearGradient(0, y, 0, y + h);
      grd.addColorStop(0, '#060a11');
      grd.addColorStop(.5, '#0c1420');
      grd.addColorStop(1, '#04070c');
      ctx.fillStyle = grd;
      ctx.fillRect(0, y, W, h);
      ctx.fillStyle = 'rgba(255,255,255,.07)';
      ctx.fillRect(0, y, W, 1);
      ctx.fillRect(0, y + h - 1, W, 1);

      ctx.save();
      ctx.beginPath();
      ctx.rect(0, y + 2, W, h - 4);
      ctx.clip();

      const text = opts.ribbonText || `AIRBALL ARENA   ✦   ${theme.label1 || 'P1'}  VS  ${theme.label2 || 'P2'}   ✦   2 PLAYER SHOWDOWN   ✦   `;
      const speed = 62;
      const offset = (t * speed) % 1400;
      ctx.font = '700 19px "Bahnschrift","Arial Narrow",sans-serif';
      const tw = ctx.measureText(text).width;
      const col = theme.a.secondary || '#ffc247';
      for (let k = -1; k < 4; k++){
        const x = -offset + k * tw;
        ctx.save();
        ctx.translate(x, y + h / 2 + 1);
        ctx.globalAlpha = .8;
        ctx.fillStyle = col;
        ctx.shadowColor = col;
        ctx.shadowBlur = 14;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(text, 0, 0);
        ctx.restore();
      }
      // colour bleed
      ctx.globalCompositeOperation = 'lighter';
      const bg = ctx.createLinearGradient(0, y, 0, y + h);
      bg.addColorStop(0, 'rgba(255,160,40,.05)');
      bg.addColorStop(.5, 'rgba(255,160,40,.12)');
      bg.addColorStop(1, 'rgba(255,160,40,0)');
      ctx.fillStyle = bg;
      ctx.fillRect(0, y, W, h);
