      ctx.save();
      ctx.beginPath();
      ctx.rect(bX, bTop, boardW, bBot - bTop);
      ctx.clip();
      ctx.strokeStyle = 'rgba(220,240,255,.25)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 5; i++){
        ctx.beginPath();
        ctx.moveTo(bX - 30 + i * 26, bBot);
        ctx.lineTo(bX + 40 + i * 26, bTop);
        ctx.stroke();
      }
      ctx.restore();
