      ctx.fillRect(bX, bTop, 40 * dir, bBot - bTop);

      /* --- rim --- */
      const rimY = C.RIM_Y, half = C.RIM_HALF;
      // support bracket
      ctx.strokeStyle = '#d9611a';
      ctx.lineWidth = 9;
