    ctx.moveTo(x1 - Math.sin(ang) * r1 * .72, y1 + Math.cos(ang) * r1 * .72);
    ctx.lineTo(x2 - Math.sin(ang) * r2 * .72, y2 + Math.cos(ang) * r2 * .72);
