        p.moveAmt = U.clamp(Math.abs(p.vx) / 330, 0, 1);
        if (p.grounded && Math.abs(p.vx) > 26){
          p.runPhase += dt * (7.4 + p.moveAmt * 6.4) * U.sign(p.vx || 1);
          p.runDust += dt * (7 + p.moveAmt * 6);
          if (p.runDust > 1){
            p.runDust = 0;
            if (p.moveAmt > .5) this.particles.push({
              kind: 'dust', x: p.x - U.sign(p.vx) * 14, y: C.FLOOR_Y - 2,
              vx: U.rand(-30, -90) * U.sign(p.vx || 1), vy: U.rand(-10, -40),
              life: .5, t: 0, color: '#b98a58', size: U.rand(5, 2), rot: 0, spin: 0, grav: 40
            });
          }
        }

        // state
        if (p.dunk) {
          // handled by updateDunk
        } else if (p.stumbleT > 0) p.state = 'stumble';
        else if (p.charging) p.state = 'charge';
        else if (!p.grounded) p.state = (p.state === 'block') ? 'block' : 'jump';
        else if (p.landT > 0) p.state = 'land';
        else if (Math.abs(p.vx) > 26) p.state = 'run';
        else p.state = 'idle';

        if (p.charging){
          p.chargeT += dt;
          p.chargePower = p.chargeT / .78;
          if (p.chargePower > 1.3) this.releaseShot(p);
          if (p.chargeT > .1 && Math.random() < dt * 8 && p.onFire) {
            this.particles.push({ kind:'fire', x:p.x + U.rand(-16,16), y:C.FLOOR_Y - p.z - U.rand(30,120), vx:U.rand(-14,14), vy:-U.rand(40,110), life:.5, t:0, color:'#ff8a2a', size:U.rand(6,2), rot:0, spin:0, grav:-60 });
          }
        }

        // coins: momentum run
        if (p.onFire && Math.random() < dt * 16){
          this.particles.push({ kind:'fire', x: p.x + U.rand(-18,18), y: C.FLOOR_Y - p.z - U.rand(10, 90), vx: U.rand(-10,10), vy: -U.rand(40,110), life: .55, t: 0, color: Math.random() < .5 ? '#ff8a2a' : '#ffc247', size: U.rand(7,3), rot: 0, spin: 0, grav: -50 });
        }
      }

      // player collision (physical jostle)
      const [a, b] = this.players;
      const dx = b.x - a.x;
      const minD = 54;
      if (Math.abs(dx) < minD && Math.abs((a.z) - (b.z)) < 100){
        const push = (minD - Math.abs(dx)) * .5;
        const dir = dx === 0 ? (a.idx === 0 ? -1 : 1) : U.sign(dx);
        const sa = .5 + (b.data.attrs.strength - a.data.attrs.strength) / 320;
        const s = U.clamp(sa, .25, .75);
        a.x -= dir * push * s * 2 * .5;
        b.x += dir * push * (1 - s) * 2 * .5;
        a.x = U.clamp(a.x, C.COURT_L + 36, C.COURT_R - 36);
        b.x = U.clamp(b.x, C.COURT_L + 36, C.COURT_R - 36);
        if (a.hasBall && Math.random() < .3) a.pickupLock = Math.max(a.pickupLock, 0);
      }

      // dribble sound
      for (const p of this.players){
        if (p.hasBall && !p.charging && p.state !== 'dunk'){
          const prev = p.dribblePhase;
          p.dribblePhase = (p.dribblePhase + dt * (1.65 + p.moveAmt * 1.5)) % 1;
          if (p.dribblePhase < prev){
            AB.Audio.dribble(p.moveAmt > .5 ? 1 : .6, this.pan(p.x));
          }
        } else if (p.hasBall) {
          p.dribblePhase = (p.dribblePhase + dt * .8) % 1;
        }
      }
    },

    pan(x){ return U.clamp((x / C.W - .5) * 1.5, -.85, .85); },

    jump(p){
      if (p.stamina < 14){
        this.popup('TIRED', p.x, C.FLOOR_Y - this.playerH(p) - 30, '#ff8a6b', 18, .7);
        return;
      }
      const jh = (98 + p.data.attrs.jump * .55) * (p.stamina < 40 ? .8 : 1) * (p.onFire ? 1.04 : 1);
      p.vz = -Math.sqrt(2 * C.GRAVITY * jh);
      p.z = Math.max(1, p.z);
      p.grounded = false;
      p.stamina -= 13;
      p.landT = 0;
      AB.Audio.jump(this.pan(p.x));
      if (!p.hasBall && !p.dunk) p.state = 'block';
      p.blockT = 0.34;
      this.burst(p.x, C.FLOOR_Y - 1, '#c9a274', 4, 'dust', 60);
    },

    action(p){
      if (p.charging) return;
      if (p.hasBall && p.grounded && !p.dunk){
        if (p.dunk) return;
        if (this.distToRim(p) < C.DUNK_DIST){
          this.startDunk(p);
        } else {
          this.startCharge(p);
        }
        return;
      }
      if (p.hasBall) return;

      if (!p.grounded){
        // block attempt window
        if (p.stamina > 8){
          p.blockT = .38;
          p.state = 'block';
          p.stamina -= 8;
          AB.Audio.jump(this.pan(p.x));
        }
        return;
      }
      this.trySteal(p);
    },

    startCharge(p){
      p.charging = true;
      p.chargeT = 0;
      p.chargePower = 0;
      p.shotDist = this.distToRim(p);
      p.state = 'charge';
      AB.Audio.ui();
    },

    cancelCharge(p){
      p.charging = false;
      p.chargeT = 0;
      p.chargePower = 0;
      if (p.state === 'charge') p.state = 'idle';
    },

    releaseShot(p){
      if (!p.charging) return;
      const meter = p.chargeT / .78;
      const q = U.clamp(1 - Math.abs(meter - .94) / .58, 0, 1);
      p.charging = false;
      p.chargeT = 0;
      p.chargePower = 0;
      p.state = 'release';
      p.stateT = 0;
      p.stamina = Math.max(0, p.stamina - 6);

      const rimX = this.ownRim(p);
      const dist = Math.abs(p.x - rimX);
      const three = dist > C.THREE_DIST;
      const a = p.data.attrs;
      const base = (three ? a.three : a.mid) / 100;
      const rangeK = three ? U.clamp(1 - (dist - C.THREE_DIST) / 800 * .2, .74, 1) : U.clamp(1 - dist / 900 * .1, .9, 1);
      const contest = this.contestFactor(p);
      const timing = .45 + .55 * q;
      const clutch = ((this.quarter >= 4) && this.clock < 20) ? (0.92 + a.clutch / 100 * .18) : 1;
      const fire = p.onFire ? 1.1 : 1;
      let acc = U.clamp(base * rangeK * timing * contest * clutch * fire, .04, .985);

      p.stats.fga++;
      const points = three ? 3 : 2;
      const errBase = Math.pow(1 - acc, 1.12) * 94 + 3;
      const ex = (Math.random() + Math.random() - 1) * errBase;
      const et = (Math.random() - .5) * (1 - acc) * .1;

      const handX = p.x + p.facing * .16 * this.playerH(p);
      const handY = C.FLOOR_Y - p.z - 1.1 * this.playerH(p);
      const tx = rimX + ex * p.attackDir;
      const ty = C.RIM_Y - 5;
      const flight = U.clamp(.76 + dist / 1600, .82, 1.2) + et;

      const b = this.ball;
      b.state = 'shot';
      b.owner = null;
      p.hasBall = false;
      b.shooter = p;
      b.points = points;
      b.scoreable = true;
      b.catchable = false;
      b.blocked = false;
      b.hitRim = false;
      b.trail = [];
      b.x = handX; b.y = handY;
      b.vx = (tx - handX) / flight;
      b.vy = (ty - handY - .5 * C.GRAVITY * flight * flight) / flight;
      b.spin = -U.sign(b.vx) * 9;
      b.life = 0;
      b.flash = 1;
      if (q > .8) {
        b.flash = 2;
        this.popup('PERFECT', p.x, C.FLOOR_Y - 280, '#8cff9e', 20, .9);
      }
      AB.Audio.jump(this.pan(p.x));
      this.burst(handX, handY, '#ffcf85', 6, 'spark', 130);
    },

    contestFactor(shooter){
      const d = this.opponent(shooter);
      const dx = Math.abs(d.x - shooter.x);
      if (dx > 150) return 1;
      let c = 1 - (1 - U.clamp(dx / 150, 0, 1)) * .22;
      if (d.z > 20) c -= .12 * U.clamp(d.z / 140, .25, 1);
      if (d.blockT > 0) c -= .08;
      c -= d.data.attrs.block / 100 * .06;
      return U.clamp(c, .58, 1);
    },

    /* ---------------- steal ---------------- */
    trySteal(def){
      if (def.stealCd > 0) return;
      def.stealCd = .62;
      const off = this.players.find(p => p.hasBall);
      if (!off || off === def) return;
      const dx = off.x - def.x;
      const near = Math.abs(dx) < 108 && Math.abs(off.z - def.z) < 80;
      if (!near){
        def.stamina = Math.max(0, def.stamina - 4);
        def.state = 'steal';
        def.stateT = 0;
        AB.Audio.jump(this.pan(def.x));
        return;
      }
      if (off.graceT > 0 || off.state === 'dunk') return;
      if (def.stamina < 10) return;
      def.stamina = Math.max(0, def.stamina - 9);
      def.state = 'steal'; def.stateT = 0;
      AB.Audio.jump(this.pan(def.x));

      let chance = .36 + (def.data.attrs.steal - off.data.attrs.handle) / 190;
      if (off.charging) chance += .14;
      chance = U.clamp(chance, .12, .72);

      if (Math.random() < chance){
        // knock the ball loose — scramble
        const b = this.ball;
        b.state = 'loose';
        b.owner = null;
        off.hasBall = false;
        off.charging = false;
        off.stumbleT = .3;
        off.state = 'stumble';
        off.stateT = 0;
        b.catchable = true;
        b.scoreable = false;
        b.shooter = null;
        const away = U.sign(off.x - def.x) || def.facing;
        b.x = off.x + away * 26;
        b.y = C.FLOOR_Y - 92;
        b.vx = away * U.rand(300, 190) + def.vx * .2;
        b.vy = U.rand(-520, -360);
        b.spin = away * 12;
        off.pickupLock = .46;
        def.pickupLock = .16;
        AB.Audio.steal(this.pan(def.x));
        this.popup('STRIPPED!', off.x, C.FLOOR_Y - 190, '#9fe8ff', 26, 1.1);
        this.addShake(5);
        this.crowdLevel = Math.min(1, this.crowdLevel + .3);
        AB.Audio.roar(.35);
        def.stats.steals++;
        this.burst(b.x, b.y, '#ffffff', 8, 'spark', 200);
      } else {
        def.stumbleT = .3;
        def.state = 'stumble'; def.stateT = 0;
        AB.Audio.land(this.pan(def.x), .5);
      }
    },

    /* ---------------- dunk ---------------- */
    startDunk(p){
      if (!p.hasBall || !p.grounded || p.stamina < 18) return;
      const rimX = this.ownRim(p);
      p.charging = false;
      p.dunk = {
        t: 0,
        dur: 1.05,
        sx: p.x, sz: 0,
        tx: U.clamp(rimX - p.attackDir * 74, C.COURT_L + 50, C.COURT_R - 50),
        peak: 205,
        scored: false,
        blocked: false,
        slam: false
      };
      p.state = 'dunk';
      p.stateT = 0;
      p.stamina -= 24;
      p.graceT = 2;
      const b = this.ball;
      b.state = 'dunk';
      b.owner = p;
      b.shooter = p;
      b.points = 2;
      b.catchable = false;
      b.scoreable = false;
      b.blocked = false;
      AB.Audio.jump(this.pan(p.x));
      this.crowdLevel = Math.min(1, this.crowdLevel + .25);
      this.popup('DUNK!', p.x, C.FLOOR_Y - 230, p.idx === 0 ? C.P1_COLOR : C.P2_COLOR, 30, .9);
    },

    updateDunk(p, dt){
      const d = p.dunk;
      d.t += dt;
      const k = U.clamp(d.t / d.dur, 0, 1);
      // phases: crouch 0-.16, rise .16-.58, slam .58-.72, fall .72-1
      let z = 0;
      if (k < .16) z = U.easeInCubic(k / .16) * 12;
      else if (k < .58) z = 12 + U.easeOutCubic((k - .16) / .42) * (d.peak - 12);
      else if (k < .74) z = d.peak - U.easeInCubic((k - .58) / .16) * 24;
      else z = U.lerp(d.peak - 24, 0, U.easeInCubic((k - .74) / .26));
      p.z = z;
      const xk = U.clamp((k - .08) / .55, 0, 1);
      p.x = U.lerp(d.sx, d.tx, U.easeOutCubic(xk));
      p.grounded = false;
      p.vz = 0;

      // ball follows the hand
      const b = this.ball;
      b.state = 'dunk';
      b.owner = p;
      b.x = p.x + p.attackDir * 26;
      const handLift = .95 + (k > .3 ? .2 : 0);
      b.y = C.FLOOR_Y - p.z - handLift * this.playerH(p);

      // block window
      if (!d.blocked && k > .18 && k < .62){
        const def = this.opponent(p);
        if (def.blockT > 0 && def.z > 35 && Math.abs(def.x - p.x) < 155){
          d.blocked = true;
          p.dunk = null;
          p.state = 'stumble'; p.stateT = 0;
          p.stumbleT = .5;
          p.z = Math.max(p.z, 60);
          p.vz = -80;
          b.state = 'loose';
          b.owner = null;
          b.catchable = true;
          b.scoreable = false;
          b.shooter = null;
          b.x = p.x - p.attackDir * 20;
          b.y = C.FLOOR_Y - p.z - 140;
          b.vx = -p.attackDir * 260;
          b.vy = -260;
          p.hasBall = false;
          def.stats.blocks++;
          this.addShake(16);
          this.doFlash(.5);
          this.popup('STUFFED!', p.x, C.FLOOR_Y - 300, '#ff6b4a', 40, 1.4);
          AB.Audio.block(this.pan(def.x));
          AB.Audio.roar(.95);
          this.crowdLevel = 1;
          this.burst(b.x, b.y, '#ffd27a', 26, 'spark', 420);
          return;
        }
      }

      // slam
      if (!d.blocked && k >= .62 && !d.slam){
        d.slam = true;
        b.y = C.RIM_Y + 24;
        const rimIdx = p.attackDir > 0 ? 0 : 1;
        this.hoops[rimIdx].netKick = 1;
        this.hoops[rimIdx].netSide = p.attackDir * 1;
        this.scoreBasket(p, 2, true, rimIdx);
      }

      if (k >= 1){
        p.dunk = null;
        p.state = 'land';
        p.stateT = 0;
        p.z = 0; p.grounded = true; p.vz = 0;
        p.landT = .16;
        p.hasBall = false;
        AB.Audio.land(this.pan(p.x), 1.3);
        this.addShake(4);
      }
    },

    /* ---------------- scoring ---------------- */
    scoreBasket(p, points, isDunk, rimIdx){
      const team = rimIdx === 0 ? 0 : 1;   // right rim -> P1, left rim -> P2
      const scorer = this.players[team];
      // credit the actual shot maker's stats
      const shooter = p || scorer;
      this.score[team] += points;
      scorer.streak = (shooter === scorer) ? scorer.streak + 1 : 1;
      scorer.stats.pts += points;
      if (shooter === scorer){
        scorer.stats.fgm++;
        if (isDunk) scorer.stats.dunks++;
      }
      scorer.stats.bestStreak = Math.max(scorer.stats.bestStreak, scorer.streak);
      if (scorer.streak >= 3 && !scorer.onFire){
        scorer.onFire = true;
        scorer.fireT = 18;
        AB.Audio.fire();
        this.popup('ON FIRE!', scorer.x, C.FLOOR_Y - 260, '#ffb03a', 34, 1.5);
        this.burst(scorer.x, C.FLOOR_Y - 120, '#ff8a2a', 24, 'spark', 260);
      } else if (scorer.onFire){
        scorer.fireT = Math.max(scorer.fireT, 12);
      }

      const rimX = rimIdx === 0 ? C.RIM_R : C.RIM_L;
      const col = team === 0 ? C.P1_COLOR : C.P2_COLOR;
      this.doFlash(isDunk ? .6 : .25);
      this.addShake(isDunk ? 18 : 4);
      this.popup(`+${points}`, rimX, C.RIM_Y - 60, col, isDunk ? 52 : 40, 1.3);
      const words = isDunk ? ['POSTERIZED!', 'THROW IT DOWN!', 'UNREAL!'] : (points === 3 ? ['SPLASH!', 'FROM DEEP!', 'CASH!'] : ['BUCKET!', 'SMOOTH.', 'COUNT IT!']);
      this.popup(words[(Math.random() * words.length) | 0], rimX, C.RIM_Y - 112, '#ffffff', 22, 1.4);
      this.burst(rimX, C.RIM_Y + 20, '#ffd27a', isDunk ? 30 : 14, 'spark', 360);
      AB.Audio.swish(this.pan(rimX));
      AB.Audio.roar(isDunk ? 1 : .6, this.pan(rimX));
      this.crowdLevel = Math.min(1, this.crowdLevel + (isDunk ? .7 : .4));
      this.slow = isDunk ? .45 : 0;

      // flash the scorer
      if (isDunk) scorer.celebrate = 1;

      this.phase = 'dead';
      this.deadT = isDunk ? 2.2 : 1.5;
      this.deadNext = () => this.placePossession(1 - team);
      this.ballFanfare(rimX);
    },

    ballFanfare(rimX){
      // little confetti from the rim
      for (let i = 0; i < 18; i++){
        this.particles.push({
          kind: 'confetti',
          x: rimX + U.rand(-40, 40), y: C.RIM_Y + 30,
          vx: U.rand(-180, 180), vy: U.rand(-460, -160),
          life: U.rand(2.2, 1.2), t: 0,
          color: U.pick(['#ffd166', '#ff7a1a', '#37d9ff', '#ffffff', '#ff4d7e']),
          size: U.rand(8, 4), rot: Math.random() * 6, spin: U.rand(10, -10), grav: 520
        });
      }
    },

    /* ---------------- ball ---------------- */
    updateBall(dt, live){
      const b = this.ball;
      b.prevY = b.y;
      b.rot += b.spin * dt;

      if (b.state === 'held' || b.state === 'dunk'){
        const p = this.players.find(x => x.hasBall) || b.owner;
        if (!p) { b.state = 'loose'; b.catchable = true; return; }
        if (b.state === 'held' && p.charging){
          const ch = U.clamp(p.chargePower, 0, 1.15);
          const H = this.playerH(p);
          b.x = p.x + p.facing * .16 * H;
          b.y = C.FLOOR_Y - p.z - (.72 + .41 * U.clamp(ch, 0, 1)) * H;
          p.ballAnim = { x: b.x, y: b.y };
          b.vx = 0; b.vy = 0;
        } else if (b.state === 'held'){
          const k = Math.abs(Math.sin(p.dribblePhase * Math.PI));
          b.x = p.x + p.facing * 40;
          b.y = C.FLOOR_Y - p.z - 28 - k * (86 - U.clamp(Math.abs(p.vx) * .05, 0, 14));
          p.ballAnim = { x: b.x, y: b.y };
          b.vx = 0; b.vy = 0;
        }
        if (b.trail.length) b.trail.length = 0;
        return;
      }

      // physics
      b.vy += C.GRAVITY * dt;
      b.vx *= Math.exp(-.16 * dt);
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life += dt;

      if (b.state === 'shot'){
        // block check
        if (b.life < .34){
          for (const d of this.players){
            if (d === b.shooter || d.blockT <= 0) continue;
            if (!d.data) continue;
            const hh = this.playerH(d);
            const hx = d.x + d.facing * 20;
            const hy = C.FLOOR_Y - d.z - (1.0 + (d.z > 20 ? .1 : 0)) * hh;
            if (U.dist(b.x, b.y, hx, hy) < 62 || U.dist(b.x, b.y, hx, hy - 30) < 56){
              this.blockShot(d, b);
              break;
            }
          }
        }
      }

      // rim collisions
      for (let s = 0; s < 2; s++){
        const rimX = s === 0 ? C.RIM_L : C.RIM_R;
        for (const side of [-1, 1]){
          const cx = rimX + side * (C.RIM_HALF - 3);
          const cy = C.RIM_Y;
          const dx = b.x - cx, dy = b.y - cy;
          const dist = Math.hypot(dx, dy);
          const rr = b.r + C.RIM_RADIUS;
          if (dist < rr && dist > .01){
            const nx = dx / dist, ny = dy / dist;
            b.x = cx + nx * rr;
            b.y = cy + ny * rr;
            const vn = b.vx * nx + b.vy * ny;
            if (vn < 0){
              b.vx -= 1.5 * vn * nx;
              b.vy -= 1.5 * vn * ny;
              b.vx *= .82; b.vy *= .82;
              b.vx += U.rand(-40, 40);
              b.spin += U.rand(-6, 6);
              b.hitRim = true;
              b.catchable = true;
              if (b.state === 'shot') b.scoreable = true;
              const hi = s === 0 ? 0 : 1;
              this.hoops[hi].rimFlash = 1;
              this.hoops[hi].netKick = Math.max(this.hoops[hi].netKick, .35);
              AB.Audio.rim(this.pan(cx));
              this.addShake(2.2);
              this.burst(cx, cy, '#ffb15a', 4, 'spark', 150);
            }
          }
        }
      }

      // backboard
      const boardInner = b.x > 800 ? C.BOARD_R_X - C.BOARD_W : C.BOARD_L_X + C.BOARD_W;
      const nearBoard = Math.abs(b.x - boardInner) < b.r + 4;
      if (nearBoard && b.y > C.BOARD_TOP && b.y < C.BOARD_BOT){
        const away = b.x > 800 ? -1 : 1;
        if (U.sign(b.vx) === -away || Math.abs(b.vx) < 1){
          b.x = boardInner + away * (b.r + 5);
          b.vx = away * Math.abs(b.vx) * .62 + away * 30;
          b.vy *= .9;
          b.spin *= .7;
          b.catchable = true;
          if (b.state === 'shot') b.scoreable = true;
          AB.Audio.glass(this.pan(b.x));
          this.addShake(3.5);
          this.burst(b.x, b.y, '#cfe8ff', 5, 'spark', 130);
        }
      }

      // score detection
      if (b.state === 'shot' && b.scoreable && b.vy > 0){
        for (let s = 0; s < 2; s++){
          const rimX = s === 0 ? C.RIM_L : C.RIM_R;
          if (b.prevY < C.RIM_Y - 2 && b.y >= C.RIM_Y - 2 && b.y < C.RIM_Y + 36 &&
              Math.abs(b.x - rimX) < C.RIM_HALF - 13 + b.r * .4){
            this.hoops[s].netKick = 1;
            this.hoops[s].netSide = U.sign(b.vx);
            const shooter = b.shooter || this.players[0];
            this.scoreBasket(shooter, b.points, false, s);
            b.scoreable = false;
            b.catchable = false;
            b.vx *= .25;
            b.vy = Math.max(b.vy, 200);
            return;
          }
        }
      }

      // floor
      if (b.y + b.r > C.FLOOR_Y){
        b.y = C.FLOOR_Y - b.r;
        if (Math.abs(b.vy) > 60){
          b.vy = -Math.abs(b.vy) * .66;
          b.vx *= .9;
          b.spin = b.vx * .02;
          b.catchable = true;
          if (b.state === 'shot') b.scoreable = true;
          AB.Audio.bounce(U.clamp(Math.abs(b.vy) / 480, .3, 1), this.pan(b.x));
          this.burst(b.x, C.FLOOR_Y, '#d6a56b', 4, 'dust', 70);
        } else {
          b.vy = 0;
          b.vx *= Math.exp(-5 * dt);
          b.catchable = true;
          if (b.state === 'shot'){
            // shot is over
            b.state = 'loose';
            b.shooter = null;
            b.scoreable = false;
            this.missResolved(b.x);
          }
        }
      }

      // screen edges
      if (b.x < 30 && b.vx < 0){ b.x = 30; b.vx = Math.abs(b.vx) * .5; }
      if (b.x > C.W - 30 && b.vx > 0){ b.x = C.W - 30; b.vx = -Math.abs(b.vx) * .5; }
      if (b.y < 40 && b.vy < 0){ b.y = 40; b.vy = Math.abs(b.vy) * .4; }

      // trail
      if (b.state === 'shot' || b.state === 'loose'){
        if (b.state === 'shot' || Math.abs(b.vy) > 300){
          b.trail.push({ x: b.x, y: b.y });
          if (b.trail.length > 12) b.trail.shift();
        }
      }

      // pickups
      if (live && b.state !== 'dunk' && b.catchable){
        this.checkPickup();
      }

      // stuck / lost ball safety
      if (live && b.state === 'loose'){
        b.life += 0;
      }
    },

    blockShot(def, b){
      b.blocked = true;
      b.state = 'loose';
      b.scoreable = false;
      b.catchable = true;
      b.shooter = null;
      b.vx = -b.vx * .35 + def.facing * 240;
      b.vy = 200;
      b.spin = 8;
      b.trail.length = 0;
      def.stats.blocks++;
      this.popup('BLOCKED!', b.x, b.y - 45, '#ff6b4a', 34, 1.2);
      this.addShake(12);
      this.doFlash(.32);
      this.slow = .3;
      AB.Audio.block(this.pan(def.x));
      AB.Audio.roar(.8);
      this.crowdLevel = 1;
      this.burst(b.x, b.y, '#ffffff', 16, 'spark', 320);
    },

    missResolved(x){
      this.markMiss();
      this.crowdLevel = Math.max(.1, this.crowdLevel - .1);
    },

    markMiss(){
      for (const p of this.players){
        if (!p.hasBall) continue;
      }
      // reset streak of the last shooter handled below
    },

    checkPickup(){
      const b = this.ball;
      if (b.state === 'held') return;
      let best = null, bestD = 1e9;
      for (const p of this.players){
        if (p.pickupLock > 0) continue;
        if (p.state === 'dunk') continue;
        const h = this.playerH(p);
        const hx = p.x + p.facing * 12;
        const hy = C.FLOOR_Y - p.z - (0.94 + (p.z > 20 ? .16 : 0)) * h;
        const d = U.dist(b.x, b.y, hx, hy);
        if (d < C.PICKUP_RADIUS && d < bestD){ bestD = d; best = p; }
      }
      if (best){
        this.giveBall(best);
        return;
      }
      // flying rebound catch
      for (const p of this.players){
        if (p.pickupLock > 0) continue;
        const d = U.dist(b.x, b.y, p.x, C.FLOOR_Y - p.z - this.playerH(p) * .62);
        if (d < 34){ this.giveBall(p); return; }
      }
    },

    giveBall(p){
      const b = this.ball;
      const prevOwner = b.shooter || b.owner;
      if (b.state === 'shot' && b.shooter && b.shooter !== p){
        // blocked/rebounded miss
      }
      if (b.state === 'shot'){
        // missed shot
        if (b.shooter && b.shooter !== p) b.shooter.streak = 0;
        this.markMiss();
        b.shooter = null;
      } else if (b.state === 'loose' && b.lastTouch && b.lastTouch !== p){
        // fresh possession
      }
      b.state = 'held';
      b.owner = p;
      b.lastTouch = p;
      b.catchable = false;
      b.scoreable = false;
      b.trail.length = 0;
      b.shooter = null;
      p.hasBall = true;
      p.charging = false;
      p.chargeT = 0;
      p.pickupLock = 0;
      p.graceT = .34;
      p.stumbleT = 0;
      p.dribblePhase = 0;
      p.state = 'idle';
      // new possession -> reset shot clock if the other team had it
      this.shotClock = C.SHOT_CLOCK;
      AB.Audio.grab(this.pan(p.x));
      this.burst(b.x, b.y, '#ffd9a3', 6, 'spark', 150);
      this.popup(p.idx === 0 ? 'P1 BALL' : 'P2 BALL', p.x, C.FLOOR_Y - 250, p.idx === 0 ? C.P1_COLOR : C.P2_COLOR, 16, .7);
    },

    /* ---------------- rules ---------------- */
    violation(){
      if (this.phase !== 'live') return;
      AB.Audio.whistle();
      this.popup('SHOT CLOCK', 800, 250, '#ffb03a', 36, 1.6);
      const holder = this.players.find(p => p.hasBall);
      const next = holder ? this.players[1 - holder.idx] : this.players[0];
      if (holder){ holder.hasBall = false; holder.charging = false; }
      this.phase = 'dead';
      this.deadT = 1.5;
      this.deadNext = () => this.placePossession(next.idx);
      this.ball.state = 'loose';
      this.ball.catchable = false;
      this.crowdLevel = .5;
    },

    endQuarter(){
      if (this.phase === 'break' || this.phase === 'over') return;
      this.phase = 'break';
      this.breakT = 4.2;
      this.clock = 0;
      this.awaitShot = false;
      this.players.forEach(p => { p.charging = false; p.hasBall = false; p.state = 'idle'; });
      this.ball.state = 'loose';
      this.ball.catchable = false;
      AB.Audio.buzzer();
      AB.Audio.crowd(.6);
      if (AB.UI) AB.UI.showQuarterBanner(this);
    },

    afterBreak(){
      const tied = this.score[0] === this.score[1];
      if (this.quarter >= 4){
        if (tied || this.quarter > 4){
          if (tied){
            this.quarter++;
            this.clock = C.OVERTIME_TIME;
            this.placeTipoff();
            this.phase = 'countdown';
            this.countdownT = 3.4;
            this.popup(this.quarter === 5 ? 'OVERTIME' : 'DOUBLE OT', 800, 280, '#ffd166', 46, 2);
            AB.Audio.roar(.7);
            return;
          }
          this.gameOver();
          return;
        }
        this.gameOver();
        return;
      }
      this.quarter++;
      this.clock = C.QUARTER_TIME;
      this.placeTipoff();
      this.phase = 'countdown';
      this.countdownT = 3.2;
      AB.Audio.beep();
    },

    gameOver(){
      this.phase = 'over';
      this.clock = 0;
      this.players.forEach(p => { p.charging = false; p.state = 'celebrate'; p.celebrate = 0; });
      AB.Audio.buzzer();
      AB.Audio.roar(1);
      this.crowdLevel = 1;
      for (let i = 0; i < 90; i++){
        this.particles.push({
          kind: 'confetti',
          x: U.rand(100, 1500), y: U.rand(-100, 200),
          vx: U.rand(-120, 120), vy: U.rand(80, 280),
          life: U.rand(5, 3), t: 0,
          color: U.pick(['#ffd166', '#ff7a1a', '#37d9ff', '#ffffff', '#ff4d7e', '#7bffca']),
          size: U.rand(10, 5), rot: Math.random() * 6, spin: U.rand(8, -8), grav: 240
        });
      }
      if (AB.UI) AB.UI.showResults(this);
    },

    /* ---------------- particles / popups ---------------- */
    updateParticles(dt){
      const parts = this.particles;
      for (let i = parts.length - 1; i >= 0; i--){
        const p = parts[i];
        p.t += dt;
        if (p.t >= p.life){ parts.splice(i, 1); continue; }
        p.vy += p.grav * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.rot += p.spin * dt;
        if (p.kind === 'confetti' && p.y + p.size > C.FLOOR_Y){
          p.y = C.FLOOR_Y - p.size;
          p.vy *= -.25;
          p.vx *= .6;
        }
      }
    },

    updatePopups(dt){
      for (let i = this.popups.length - 1; i >= 0; i--){
        const p = this.popups[i];
        p.t += dt;
        p.y += p.vy * dt;
        p.vy *= (1 - dt * 1.4);
        if (p.t >= p.life) this.popups.splice(i, 1);
      }
    },

    getSnapshot(){
      return {
        score: this.score.slice(),
        quarter: this.quarter,
        clock: this.clock,
        shotClock: this.shotClock,
        players: this.players.map(p => ({
          name: p.data.name, short: p.data.short, num: p.data.num,
          team: p.data.abbr, score: this.score[p.idx],
          stamina: p.stamina, onFire: p.onFire, fireT: p.fireT,
          stats: p.stats, colors: p.data.colors
        })),
        mode: this.mode, phase: this.phase
      };
    }
  };
})();

