326:     /* ============================================================
327:        update
328:        ============================================================ */
329:     update(dt){
330:       this.t += dt;
331:       this.beat += dt;
332:       this.shake = Math.max(0, this.shake - dt * 60);
333:       this.flash = Math.max(0, this.flash - dt * 2.6);
334:       this.slow = Math.max(0, this.slow - dt);
335:       this.crowdLevel = Math.max(0, this.crowdLevel - dt * .18);
336:       this.updateParticles(dt);
337:       this.updatePopups(dt);
338: 
339:       if (this.mode === 'attract'){
340:         this.updateAttract(dt);
341:         return;
342:       }
343:       if (this.paused) return;
344: 
345:       if (this.phase === 'countdown'){
346:         this.countdownT -= dt;
347:         this.updatePlayers(dt, false);
348:         this.updateHoopAnim(dt);
349:         if (this.countdownT <= 0){
350:           this.phase = 'live';
351:           this.countdownT = 0;
352:           this.ball.vy = 40;
353:           this.popup('BALL!', 800, 300, '#ffd166', 46, .7);
354:           AB.Audio.roar(.5);
355:           this.shakeIt(2);
356:         }
357:         return;
358:       }
359: 
360:       if (this.phase === 'over'){
361:         this.updatePlayers(dt, false);
362:         this.updateHoopAnim(dt);
363:         return;
364:       }
365: 
366:       if (this.phase === 'break'){
367:         this.breakT -= dt;
368:         this.updatePlayers(dt, false);
369:         this.updateHoopAnim(dt);
370:         if (this.breakT <= 0) this.afterBreak();
371:         return;
372:       }
373: 
374:       if (this.phase === 'dead'){
375:         this.deadT -= dt;
376:         this.updatePlayers(dt, false);
377:         this.updateBall(dt, false);
378:         this.updateHoopAnim(dt);
379:         if (this.deadT <= 0 && this.deadNext){
380:           const fn = this.deadNext;
381:           this.deadNext = null;
382:           fn();
383:         }
384:         return;
385:       }
386: 
387:       if (this.phase === 'live'){
388:         this.clock = Math.max(0, this.clock - dt);
389:         this.shotClock -= dt;
390:         if (this.shotClock <= 0){
391:           this.shotClock = 0;
392:           this.violation();
393:           return;
394:         }
395:         this.updatePlayers(dt, true);
396:         this.updateBall(dt, true);
397:         this.updateHoopAnim(dt);
398: 
399:         if (this.awaitShot){
400:           this.awaitT -= dt;
401:           if (this.awaitT <= 0) this.endQuarter();
402:         } else if (this.clock <= 0){
403:           if (this.ball.state === 'shot' && this.ball.shooter){
404:             this.awaitShot = true;
405:             this.awaitT = 1.7;
406:           } else {
407:             this.endQuarter();
408:           }
409:         }
410:       }
411:     },
412: 
413:     shakeIt(v){ this.addShake(v); },
414: 
415:     updateAttract(dt){
416:       this.attractT += dt;
417:       const p1 = this.players[0], p2 = this.players[1];
418:       p1.state = 'idle'; p2.state = 'idle';
419:       p1.facing = p1.attackDir;
420:       p2.facing = -1;
421:       // slow sway / warmup
422:       p2.x = 1042 + Math.sin(this.attractT * .5) * 14;
423:       p1.x = 592 + Math.cos(this.attractT * .4) * 10;
424:       p1.hasBall = true;
425:       this.ball.state = 'held';
426:       this.ball.owner = p1;
427:       p1.dribblePhase = (p1.dribblePhase + dt * 1.7) % 1;
428:       const k = Math.abs(Math.sin(p1.dribblePhase * Math.PI));
429:       this.ball.x = p1.x + 40;
430:       this.ball.y = C.FLOOR_Y - 28 - k * 84;
431:       p1.ballAnim = { x: this.ball.x, y: this.ball.y };
432:       this.ball.rot += dt * 2;
433:       for (const p of this.players){
434:         p.stateT += dt;
435:         p.moveAmt = 0;
436:         p.z = 0;
437:       }
438:       this.updateHoopAnim(dt);
439:     },
440: 
441:     updateHoopAnim(dt){
442:       for (const h of this.hoops){
443:         h.netKick = Math.max(0, h.netKick - dt * 2.2);
444:         h.rimFlash = Math.max(0, h.rimFlash - dt * 2.5);
445:         h.netSide *= (1 - dt * 2);
446:       }
447:     },
448: 
449:     updatePlayers(dt, allowInput){
450:       for (const p of this.players){
451:         p.stateT += dt;
452:         p.stealCd = Math.max(0, p.stealCd - dt);
453:         p.blockT = Math.max(0, p.blockT - dt);
454:         p.stumbleT = Math.max(0, p.stumbleT - dt);
455:         p.landT = Math.max(0, p.landT - dt);
456:         p.pickupLock = Math.max(0, p.pickupLock - dt);
457:         p.graceT = Math.max(0, p.graceT - dt);
458:         p.fireT = Math.max(0, p.fireT - dt);
459:         if (p.fireT <= 0) p.onFire = false;
460: 
461:         const canAct = allowInput && !p.stumbleT && !p.landT && !p.dunk;
462: 
463:         // stamina
464:         const regen = p.grounded ? (p.charging ? 4 : 17) : 5;
465:         p.stamina = Math.min(100, p.stamina + regen * dt);
466:         if (p.stamina < 0) p.stamina = 0;
467: 
468:         // input
469:         const L = p.idx === 0;
470:         const kLeft = L ? 'KeyA' : 'ArrowLeft';
471:         const kRight = L ? 'KeyD' : 'ArrowRight';
472:         const kJump = L ? 'KeyW' : 'ArrowUp';
473:         const kAct = L ? 'KeyF' : 'KeyL';
474:         let dir = 0;
475:         if (canAct && this.mode === 'match' && !p.charging){
476:           if (this.down(kLeft)) dir -= 1;
477:           if (this.down(kRight)) dir += 1;
478:         } else if (allowInput && p.charging){
479:           if (this.down(kLeft)) dir -= 0.25;
480:           if (this.down(kRight)) dir += 0.25;
481:         }
482: 
483:         if (allowInput){
484:           if (this.hit(kJump) && p.grounded && canAct) this.jump(p);
485:           if (this.hit(kAct) && canAct) this.action(p);
486:           if (this.up(kAct) && p.charging) this.releaseShot(p);
487:         }
488: 
489:         // movement
490:         const maxSpd = (292 + p.data.attrs.spd * 1.05) * (p.hasBall ? (0.965 - (100 - p.data.attrs.handle) / 1200) : 1) * (p.onFire ? 1.04 : 1);
491:         const accel = p.grounded ? 2300 : 1150;
492:         if (p.dunk){
493:           this.updateDunk(p, dt);
494:         } else {
495:           if (dir !== 0) p.vx += dir * accel * dt;
496:           else p.vx *= Math.exp(-(p.grounded ? 11 : 2.2) * dt);
497:           p.vx = U.clamp(p.vx, -maxSpd, maxSpd);
498:           if (Math.abs(p.vx) > maxSpd && dir === 0) p.vx = U.sign(p.vx) * maxSpd;
499:           p.x += p.vx * dt;
500:           p.x = U.clamp(p.x, C.COURT_L + 36, C.COURT_R - 36);
501: 
502:           // jump physics
503:           if (!p.grounded){
504:             p.z += p.vz * dt;
505:             p.vz += C.GRAVITY * dt;
506:             if (p.z <= 0){
507:               p.z = 0; p.vz = 0; p.grounded = true;
508:               p.landT = .12;
509:               AB.Audio.land(this.pan(p.x), .8);
510:               this.burst(p.x, C.FLOOR_Y - 2, '#caa173', 5, 'dust', 90);
511:               if (p.hasBall) p.state = 'idle';
512:             }
513:           }
514:         }
515: 
516:         // facing
517:         if (p.charging || (p.dunk && p.dunkT > 0)){
518:           p.facing = p.attackDir;
519:         } else if (p.hasBall && Math.abs(p.vx) < 45){
520:           p.facing = p.attackDir;
521:         } else if (Math.abs(p.vx) > 40){
522:           p.facing = U.sign(p.vx);
523:         } else if (!p.hasBall && this.ball && this.ball.state !== 'held'){
524:           p.facing = this.ball.x >= p.x ? 1 : -1;
525:         }
526: 
527:         // run animation
528:         p.moveAmt = U.clamp(Math.abs(p.vx) / 330, 0, 1);
529:         if (p.grounded && Math.abs(p.vx) > 26){
530:           p.runPhase += dt * (7.4 + p.moveAmt * 6.4) * U.sign(p.vx || 1);
531:           p.runDust += dt * (7 + p.moveAmt * 6);
532:           if (p.runDust > 1){
533:             p.runDust = 0;
534:             if (p.moveAmt > .5) this.particles.push({
535:               kind: 'dust', x: p.x - U.sign(p.vx) * 14, y: C.FLOOR_Y - 2,
536:               vx: U.rand(-30, -90) * U.sign(p.vx || 1), vy: U.rand(-10, -40),
537:               life: .5, t: 0, color: '#b98a58', size: U.rand(5, 2), rot: 0, spin: 0, grav: 40
538:             });
539:           }
540:         }
541: 
542:         // state
543:         if (p.dunk) {
544:           // handled by updateDunk
545:         } else if (p.stumbleT > 0) p.state = 'stumble';
546:         else if (p.charging) p.state = 'charge';
547:         else if (!p.grounded) p.state = (p.state === 'block') ? 'block' : 'jump';
548:         else if (p.state === 'steal' && p.stateT < .26) p.state = 'steal';
549:         else if (p.state === 'release' && p.stateT < .22) p.state = 'release';
550:         else if (p.state === 'celebrate' && this.phase === 'over') p.state = 'celebrate';
551:         else if (p.landT > 0) p.state = 'land';
552:         else if (Math.abs(p.vx) > 26) p.state = 'run';
553:         else p.state = 'idle';
554: 
555:         if (p.charging){
556:           p.chargeT += dt;
557:           p.chargePower = p.chargeT / .78;
558:           if (p.chargePower > 1.3) this.releaseShot(p);
559:           if (p.chargeT > .1 && Math.random() < dt * 8 && p.onFire) {
560:             this.particles.push({ kind:'fire', x:p.x + U.rand(-16,16), y:C.FLOOR_Y - p.z - U.rand(30,120), vx:U.rand(-14,14), vy:-U.rand(40,110), life:.5, t:0, color:'#ff8a2a', size:U.rand(6,2), rot:0, spin:0, grav:-60 });
561:           }
562:         }
563: 
564:         // coins: momentum run
565:         if (p.onFire && Math.random() < dt * 16){
566:           this.particles.push({ kind:'fire', x: p.x + U.rand(-18,18), y: C.FLOOR_Y - p.z - U.rand(10, 90), vx: U.rand(-10,10), vy: -U.rand(40,110), life: .55, t: 0, color: Math.random() < .5 ? '#ff8a2a' : '#ffc247', size: U.rand(7,3), rot: 0, spin: 0, grav: -50 });
567:         }
568:       }
569: 
570:       // player collision (physical jostle)
571:       const [a, b] = this.players;
572:       const dx = b.x - a.x;
573:       const minD = 54;
574:       if (Math.abs(dx) < minD && Math.abs((a.z) - (b.z)) < 100){
575:         const overlap = minD - Math.abs(dx);
576:         const dir = dx === 0 ? (a.idx === 0 ? -1 : 1) : U.sign(dx);
577:         const bias = U.clamp(.5 + (b.data.attrs.strength - a.data.attrs.strength) / 260, .18, .82);
578:         a.x -= dir * overlap * bias;
579:         b.x += dir * overlap * (1 - bias);
580:         a.x = U.clamp(a.x, C.COURT_L + 36, C.COURT_R - 36);
581:         b.x = U.clamp(b.x, C.COURT_L + 36, C.COURT_R - 36);
582:       }
583: 
584:       // dribble sound
585:       for (const p of this.players){
586:         if (p.hasBall && !p.charging && p.state !== 'dunk'){
587:           const prev = p.dribblePhase;
588:           p.dribblePhase = (p.dribblePhase + dt * (1.65 + p.moveAmt * 1.5)) % 1;
589:           if (p.dribblePhase < prev){
590:             AB.Audio.dribble(p.moveAmt > .5 ? 1 : .6, this.pan(p.x));
591:           }
592:         } else if (p.hasBall) {
593:           p.dribblePhase = (p.dribblePhase + dt * .8) % 1;
594:         }
595:       }
596:     },
597: 
598:     pan(x){ return U.clamp((x / C.W - .5) * 1.5, -.85, .85); },
599: 
600:     jump(p){
601:       if (p.stamina < 14){
602:         this.popup('TIRED', p.x, C.FLOOR_Y - this.playerH(p) - 30, '#ff8a6b', 18, .7);
603:         return;
604:       }
605:       const jh = (98 + p.data.attrs.jump * .55) * (p.stamina < 40 ? .8 : 1) * (p.onFire ? 1.04 : 1);
606:       p.vz = -Math.sqrt(2 * C.GRAVITY * jh);
607:       p.z = Math.max(1, p.z);
608:       p.grounded = false;
609:       p.stamina -= 13;
610:       p.landT = 0;
611:       AB.Audio.jump(this.pan(p.x));
612:       if (!p.hasBall && !p.dunk) p.state = 'block';
613:       p.blockT = 0.34;
614:       this.burst(p.x, C.FLOOR_Y - 1, '#c9a274', 4, 'dust', 60);
615:     },
616: 
617:     action(p){
618:       if (p.charging) return;
619:       if (p.hasBall && p.grounded && !p.dunk){
620:         if (p.dunk) return;
621:         if (this.distToRim(p) < C.DUNK_DIST){
622:           this.startDunk(p);
623:         } else {
624:           this.startCharge(p);
625:         }
626:         return;
627:       }
628:       if (p.hasBall) return;
629: 
630:       if (!p.grounded){
631:         // block attempt window
632:         if (p.stamina > 8){
633:           p.blockT = .38;
634:           p.state = 'block';
635:           p.stamina -= 8;
636:           AB.Audio.jump(this.pan(p.x));
637:         }
638:         return;
639:       }
640:       this.trySteal(p);
641:     },
642: 
643:     startCharge(p){
644:       p.charging = true;
645:       p.chargeT = 0;
646:       p.chargePower = 0;
647:       p.shotDist = this.distToRim(p);
648:       p.state = 'charge';
649:       AB.Audio.ui();
650:     },
651: 
652:     cancelCharge(p){
653:       p.charging = false;
654:       p.chargeT = 0;
655:       p.chargePower = 0;
656:       if (p.state === 'charge') p.state = 'idle';
657:     },
658: 
659:     releaseShot(p){
660:       if (!p.charging) return;
661:       const meter = p.chargeT / .78;
662:       const q = U.clamp(1 - Math.abs(meter - .94) / .58, 0, 1);
663:       p.charging = false;
664:       p.chargeT = 0;
665:       p.chargePower = 0;
666:       p.state = 'release';
667:       p.stateT = 0;
668:       p.stamina = Math.max(0, p.stamina - 6);
669: 
670:       const rimX = this.ownRim(p);
671:       const dist = Math.abs(p.x - rimX);
672:       const three = dist > C.THREE_DIST;
673:       const a = p.data.attrs;
674:       const base = (three ? a.three : a.mid) / 100;
675:       const rangeK = three ? U.clamp(1 - (dist - C.THREE_DIST) / 800 * .2, .74, 1) : U.clamp(1 - dist / 900 * .1, .9, 1);
676:       const contest = this.contestFactor(p);
677:       const timing = .45 + .55 * q;
678:       const clutch = ((this.quarter >= 4) && this.clock < 20) ? (0.92 + a.clutch / 100 * .18) : 1;
679:       const fire = p.onFire ? 1.1 : 1;
680:       let acc = U.clamp(base * rangeK * timing * contest * clutch * fire, .04, .985);
681: 
682:       p.stats.fga++;
683:       const points = three ? 3 : 2;
684:       const errBase = Math.pow(1 - acc, 1.12) * 94 + 3;
685:       const ex = (Math.random() + Math.random() - 1) * errBase;
686:       const et = (Math.random() - .5) * (1 - acc) * .1;
687: 
688:       const handX = p.x + p.facing * .16 * this.playerH(p);
689:       const handY = C.FLOOR_Y - p.z - 1.1 * this.playerH(p);
690:       const tx = rimX + ex * p.attackDir;
691:       const ty = C.RIM_Y - 5;
692:       const flight = U.clamp(.76 + dist / 1600, .82, 1.2) + et;
693: 
694:       const b = this.ball;
695:       b.state = 'shot';
696:       b.owner = null;
697:       p.hasBall = false;
698:       b.shooter = p;
699:       b.points = points;
700:       b.scoreable = true;
701:       b.catchable = false;
702:       b.blocked = false;
703:       b.hitRim = false;
704:       b.trail = [];
705:       b.x = handX; b.y = handY;
706:       b.vx = (tx - handX) / flight;
707:       b.vy = (ty - handY - .5 * C.GRAVITY * flight * flight) / flight;
708:       b.spin = -U.sign(b.vx) * 9;
709:       b.life = 0;
710:       b.flash = 1;
711:       if (q > .8) {
712:         b.flash = 2;
713:         this.popup('PERFECT', p.x, C.FLOOR_Y - 280, '#8cff9e', 20, .9);
714:       }
715:       AB.Audio.jump(this.pan(p.x));
716:       this.burst(handX, handY, '#ffcf85', 6, 'spark', 130);
717:     },
718: 
719:     contestFactor(shooter){
720:       const d = this.opponent(shooter);
721:       const dx = Math.abs(d.x - shooter.x);
722:       if (dx > 150) return 1;
723:       let c = 1 - (1 - U.clamp(dx / 150, 0, 1)) * .22;
724:       if (d.z > 20) c -= .12 * U.clamp(d.z / 140, .25, 1);
725:       if (d.blockT > 0) c -= .08;
726:       c -= d.data.attrs.block / 100 * .06;
727:       return U.clamp(c, .58, 1);
728:     },
729: 
730:     /* ---------------- steal ---------------- */
731:     trySteal(def){
732:       if (def.stealCd > 0) return;
733:       def.stealCd = .62;
734:       const off = this.players.find(p => p.hasBall);
735:       if (!off || off === def) return;
736:       const dx = off.x - def.x;
737:       const near = Math.abs(dx) < 108 && Math.abs(off.z - def.z) < 80;
738:       if (!near){
739:         def.stamina = Math.max(0, def.stamina - 4);
740:         def.state = 'steal';
741:         def.stateT = 0;
742:         AB.Audio.jump(this.pan(def.x));
743:         return;
744:       }
745:       if (off.graceT > 0 || off.state === 'dunk') return;
746:       if (def.stamina < 10) return;
747:       def.stamina = Math.max(0, def.stamina - 9);
748:       def.state = 'steal'; def.stateT = 0;
749:       AB.Audio.jump(this.pan(def.x));
750: 
751:       let chance = .36 + (def.data.attrs.steal - off.data.attrs.handle) / 190;
752:       if (off.charging) chance += .14;
753:       chance = U.clamp(chance, .12, .72);
754: 
755:       if (Math.random() < chance){
756:         // knock the ball loose — scramble
757:         const b = this.ball;
758:         b.state = 'loose';
759:         b.owner = null;
760:         off.hasBall = false;
761:         off.charging = false;
762:         off.stumbleT = .3;
763:         off.state = 'stumble';
764:         off.stateT = 0;
765:         b.catchable = true;
766:         b.scoreable = false;
767:         b.shooter = null;
768:         const away = U.sign(off.x - def.x) || def.facing;
769:         b.x = off.x + away * 26;
770:         b.y = C.FLOOR_Y - 92;
771:         b.vx = away * U.rand(300, 190) + def.vx * .2;
772:         b.vy = U.rand(-520, -360);
773:         b.spin = away * 12;
774:         off.pickupLock = .46;
775:         def.pickupLock = .16;
776:         AB.Audio.steal(this.pan(def.x));
777:         this.popup('STRIPPED!', off.x, C.FLOOR_Y - 190, '#9fe8ff', 26, 1.1);
778:         this.addShake(5);
779:         this.crowdLevel = Math.min(1, this.crowdLevel + .3);
780:         AB.Audio.roar(.35);
781:         def.stats.steals++;
782:         this.burst(b.x, b.y, '#ffffff', 8, 'spark', 200);
783:       } else {
784:         def.stumbleT = .3;
785:         def.state = 'stumble'; def.stateT = 0;
786:         AB.Audio.land(this.pan(def.x), .5);
787:       }
788:     },
789: 
790:     /* ---------------- dunk ---------------- */
791:     startDunk(p){
792:       if (!p.hasBall || !p.grounded || p.stamina < 18) return;
793:       const rimX = this.ownRim(p);
794:       p.stats.fga++;
795:       p.charging = false;
796:       p.dunk = {
797:         t: 0,
798:         dur: 1.05,
799:         sx: p.x, sz: 0,
800:         tx: U.clamp(rimX - p.attackDir * 74, C.COURT_L + 50, C.COURT_R - 50),
801:         peak: 205,
802:         scored: false,
803:         blocked: false,
804:         slam: false
805:       };
806:       p.state = 'dunk';
807:       p.stateT = 0;
808:       p.stamina -= 24;
809:       p.graceT = 2;
810:       const b = this.ball;
811:       b.state = 'dunk';
812:       b.owner = p;
813:       b.shooter = p;
814:       b.points = 2;
815:       b.catchable = false;
816:       b.scoreable = false;
817:       b.blocked = false;
818:       AB.Audio.jump(this.pan(p.x));
819:       this.crowdLevel = Math.min(1, this.crowdLevel + .25);
820:       this.popup('DUNK!', p.x, C.FLOOR_Y - 230, p.idx === 0 ? C.P1_COLOR : C.P2_COLOR, 30, .9);
821:     },
822: 
823:     updateDunk(p, dt){
824:       const d = p.dunk;
825:       d.t += dt;
826:       const k = U.clamp(d.t / d.dur, 0, 1);
827:       // phases: crouch 0-.16, rise .16-.58, slam .58-.72, fall .72-1
828:       let z = 0;
829:       if (k < .16) z = U.easeInCubic(k / .16) * 12;
830:       else if (k < .58) z = 12 + U.easeOutCubic((k - .16) / .42) * (d.peak - 12);
831:       else if (k < .74) z = d.peak - U.easeInCubic((k - .58) / .16) * 24;
832:       else z = U.lerp(d.peak - 24, 0, U.easeInCubic((k - .74) / .26));
833:       p.z = z;
834:       const xk = U.clamp((k - .08) / .55, 0, 1);
835:       p.x = U.lerp(d.sx, d.tx, U.easeOutCubic(xk));
836:       p.grounded = false;
837:       p.vz = 0;
838: 
839:       // ball follows the hand
840:       const b = this.ball;
841:       b.state = 'dunk';
842:       b.owner = p;
843:       b.x = p.x + p.attackDir * 26;
844:       const handLift = .95 + (k > .3 ? .2 : 0);
845:       b.y = C.FLOOR_Y - p.z - handLift * this.playerH(p);
846: 
847:       // block window
848:       if (!d.blocked && k > .18 && k < .62){
849:         const def = this.opponent(p);
850:         if (def.blockT > 0 && def.z > 35 && Math.abs(def.x - p.x) < 155){
851:           d.blocked = true;
852:           p.dunk = null;
853:           p.state = 'stumble'; p.stateT = 0;
854:           p.stumbleT = .5;
855:           p.z = Math.max(p.z, 60);
856:           p.vz = -80;
857:           b.state = 'loose';
858:           b.owner = null;
859:           b.catchable = true;
860:           b.scoreable = false;
861:           b.shooter = null;
862:           b.x = p.x - p.attackDir * 20;
863:           b.y = C.FLOOR_Y - p.z - 140;
864:           b.vx = -p.attackDir * 260;
865:           b.vy = -260;
866:           p.hasBall = false;
867:           def.stats.blocks++;
868:           this.addShake(16);
869:           this.doFlash(.5);
870:           this.popup('STUFFED!', p.x, C.FLOOR_Y - 300, '#ff6b4a', 40, 1.4);
871:           AB.Audio.block(this.pan(def.x));
872:           AB.Audio.roar(.95);
873:           this.crowdLevel = 1;
874:           this.burst(b.x, b.y, '#ffd27a', 26, 'spark', 420);
875:           return;
876:         }
877:       }
878: 
879:       // slam
880:       if (!d.blocked && k >= .62 && !d.slam){
881:         d.slam = true;
882:         b.y = C.RIM_Y + 24;
883:         const rimIdx = p.attackDir > 0 ? 1 : 0;
884:         this.hoops[rimIdx].netKick = 1;
885:         this.hoops[rimIdx].netSide = p.attackDir * 1;
886:         this.scoreBasket(p, 2, true, rimIdx);
887:       }
888: 
889:       if (k >= 1){
890:         p.dunk = null;
891:         p.state = 'land';
892:         p.stateT = 0;
893:         p.z = 0; p.grounded = true; p.vz = 0;
894:         p.landT = .16;
895:         p.hasBall = false;
896:         AB.Audio.land(this.pan(p.x), 1.3);
897:         this.addShake(4);
898:       }
899:     },
900: 
901:     /* ---------------- scoring ---------------- */
902:     scoreBasket(p, points, isDunk, rimIdx){
903:       const team = rimIdx === 0 ? 1 : 0;   // left rim -> P2, right rim -> P1
904:       const scorer = this.players[team];
905:       // credit the actual shot maker's stats
906:       const shooter = p || scorer;
907:       this.score[team] += points;
908:       scorer.streak = (shooter === scorer) ? scorer.streak + 1 : 1;
909:       scorer.stats.pts += points;
910:       if (shooter === scorer){
911:         scorer.stats.fgm++;
912:         if (isDunk) scorer.stats.dunks++;
913:       }
914:       scorer.stats.bestStreak = Math.max(scorer.stats.bestStreak, scorer.streak);
915:       if (scorer.streak >= 3 && !scorer.onFire){
916:         scorer.onFire = true;
917:         scorer.fireT = 18;
918:         AB.Audio.fire();
919:         this.popup('ON FIRE!', scorer.x, C.FLOOR_Y - 260, '#ffb03a', 34, 1.5);
920:         this.burst(scorer.x, C.FLOOR_Y - 120, '#ff8a2a', 24, 'spark', 260);
921:       } else if (scorer.onFire){
922:         scorer.fireT = Math.max(scorer.fireT, 12);
923:       }
924: 
925:       const rimX = rimIdx === 0 ? C.RIM_L : C.RIM_R;
926:       const col = team === 0 ? C.P1_COLOR : C.P2_COLOR;
927:       this.doFlash(isDunk ? .6 : .25);
928:       this.addShake(isDunk ? 18 : 4);
929:       this.popup(`+${points}`, rimX, C.RIM_Y - 60, col, isDunk ? 52 : 40, 1.3);
930:       const words = isDunk ? ['POSTERIZED!', 'THROW IT DOWN!', 'UNREAL!'] : (points === 3 ? ['SPLASH!', 'FROM DEEP!', 'CASH!'] : ['BUCKET!', 'SMOOTH.', 'COUNT IT!']);
931:       this.popup(words[(Math.random() * words.length) | 0], rimX, C.RIM_Y - 112, '#ffffff', 22, 1.4);
932:       this.burst(rimX, C.RIM_Y + 20, '#ffd27a', isDunk ? 30 : 14, 'spark', 360);
933:       AB.Audio.swish(this.pan(rimX));
934:       AB.Audio.roar(isDunk ? 1 : .6, this.pan(rimX));
935:       this.crowdLevel = Math.min(1, this.crowdLevel + (isDunk ? .7 : .4));
936:       this.slow = isDunk ? .45 : 0;
937: 
938:       // flash the scorer
939:       if (isDunk) scorer.celebrate = 1;
940: 
941:       this.phase = 'dead';
942:       this.deadT = isDunk ? 2.2 : 1.5;
943:       this.deadNext = () => this.placePossession(1 - team);
944:       this.ballFanfare(rimX);
945:     },
946: 
947:     ballFanfare(rimX){
948:       // little confetti from the rim
949:       for (let i = 0; i < 18; i++){
950:         this.particles.push({
951:           kind: 'confetti',
952:           x: rimX + U.rand(-40, 40), y: C.RIM_Y + 30,
953:           vx: U.rand(-180, 180), vy: U.rand(-460, -160),
954:           life: U.rand(2.2, 1.2), t: 0,
955:           color: U.pick(['#ffd166', '#ff7a1a', '#37d9ff', '#ffffff', '#ff4d7e']),
956:           size: U.rand(8, 4), rot: Math.random() * 6, spin: U.rand(10, -10), grav: 520
957:         });
958:       }
959:     },
960: 
961:     /* ---------------- ball ---------------- */
962:     updateBall(dt, live){
963:       const b = this.ball;
964:       b.prevY = b.y;
965:       b.rot += b.spin * dt;
966: 
967:       if (b.state === 'held' || b.state === 'dunk'){
968:         const p = this.players.find(x => x.hasBall) || b.owner;
969:         if (!p) { b.state = 'loose'; b.catchable = true; return; }
970:         if (b.state === 'held' && p.charging){
971:           const ch = U.clamp(p.chargePower, 0, 1.15);
972:           const H = this.playerH(p);
973:           b.x = p.x + p.facing * .16 * H;
974:           b.y = C.FLOOR_Y - p.z - (.72 + .41 * U.clamp(ch, 0, 1)) * H;
975:           p.ballAnim = { x: b.x, y: b.y };
976:           b.vx = 0; b.vy = 0;
977:         } else if (b.state === 'held'){
978:           const k = Math.abs(Math.sin(p.dribblePhase * Math.PI));
979:           b.x = p.x + p.facing * 40;
980:           b.y = C.FLOOR_Y - p.z - 28 - k * (86 - U.clamp(Math.abs(p.vx) * .05, 0, 14));
981:           p.ballAnim = { x: b.x, y: b.y };
982:           b.vx = 0; b.vy = 0;
983:         }
984:         if (b.trail.length) b.trail.length = 0;
985:         return;
986:       }
987: 
988:       // physics
989:       b.vy += C.GRAVITY * dt;
990:       b.vx *= Math.exp(-.16 * dt);
991:       b.x += b.vx * dt;
992:       b.y += b.vy * dt;
993:       b.life += dt;
994: 
995:       if (b.state === 'shot'){
996:         // block check
997:         if (b.life < .34){
998:           for (const d of this.players){
999:             if (d === b.shooter || d.blockT <= 0) continue;
1000:             if (!d.data) continue;
1001:             const hh = this.playerH(d);
1002:             const hx = d.x + d.facing * 20;
1003:             const hy = C.FLOOR_Y - d.z - (1.0 + (d.z > 20 ? .1 : 0)) * hh;
1004:             if (U.dist(b.x, b.y, hx, hy) < 62 || U.dist(b.x, b.y, hx, hy - 30) < 56){
1005:               this.blockShot(d, b);
1006:               break;
1007:             }
1008:           }
1009:         }
1010:       }
1011: 
1012:       // rim collisions
1013:       for (let s = 0; s < 2; s++){
1014:         const rimX = s === 0 ? C.RIM_L : C.RIM_R;
1015:         for (const side of [-1, 1]){
1016:           const cx = rimX + side * (C.RIM_HALF - 3);
1017:           const cy = C.RIM_Y;
1018:           const dx = b.x - cx, dy = b.y - cy;
1019:           const dist = Math.hypot(dx, dy);
1020:           const rr = b.r + C.RIM_RADIUS;
1021:           if (dist < rr && dist > .01){
1022:             const nx = dx / dist, ny = dy / dist;
1023:             b.x = cx + nx * rr;
1024:             b.y = cy + ny * rr;
1025:             const vn = b.vx * nx + b.vy * ny;
1026:             if (vn < 0){
1027:               b.vx -= 1.5 * vn * nx;
1028:               b.vy -= 1.5 * vn * ny;
1029:               b.vx *= .82; b.vy *= .82;
1030:               b.vx += U.rand(-40, 40);
1031:               b.spin += U.rand(-6, 6);
1032:               b.hitRim = true;
1033:               b.catchable = true;
1034:               if (b.state === 'shot') b.scoreable = true;
1035:               const hi = s === 0 ? 0 : 1;
1036:               this.hoops[hi].rimFlash = 1;
1037:               this.hoops[hi].netKick = Math.max(this.hoops[hi].netKick, .35);
1038:               AB.Audio.rim(this.pan(cx));
1039:               this.addShake(2.2);
1040:               this.burst(cx, cy, '#ffb15a', 4, 'spark', 150);
1041:             }
1042:           }
1043:         }
1044:       }
1045: 
1046:       // backboard
1047:       const boardInner = b.x > 800 ? C.BOARD_R_X - C.BOARD_W : C.BOARD_L_X + C.BOARD_W;
1048:       const nearBoard = Math.abs(b.x - boardInner) < b.r + 4;
1049:       if (nearBoard && b.y > C.BOARD_TOP && b.y < C.BOARD_BOT){
1050:         const away = b.x > 800 ? -1 : 1;
1051:         if (U.sign(b.vx) === -away || Math.abs(b.vx) < 1){
1052:           b.x = boardInner + away * (b.r + 5);
1053:           b.vx = away * Math.abs(b.vx) * .62 + away * 30;
1054:           b.vy *= .9;
1055:           b.spin *= .7;
1056:           b.catchable = true;
1057:           if (b.state === 'shot') b.scoreable = true;
1058:           AB.Audio.glass(this.pan(b.x));
1059:           this.addShake(3.5);
1060:           this.burst(b.x, b.y, '#cfe8ff', 5, 'spark', 130);
1061:         }
1062:       }
1063: 
1064:       // score detection
1065:       if (b.state === 'shot' && b.scoreable && b.vy > 0){
1066:         for (let s = 0; s < 2; s++){
1067:           const rimX = s === 0 ? C.RIM_L : C.RIM_R;
1068:           if (b.prevY < C.RIM_Y - 2 && b.y >= C.RIM_Y - 2 && b.y < C.RIM_Y + 36 &&
1069:               Math.abs(b.x - rimX) < 33){
1070:             this.hoops[s].netKick = 1;
1071:             this.hoops[s].netSide = U.sign(b.vx);
1072:             const shooter = b.shooter || this.players[0];
1073:             this.scoreBasket(shooter, b.points, false, s);
1074:             b.scoreable = false;
1075:             b.catchable = false;
1076:             b.vx *= .25;
1077:             b.vy = Math.max(b.vy, 200);
1078:             return;
1079:           }
1080:         }
1081:       }
1082: 
1083:       // floor
