/* ============================================================
   AIRBALL — boot + stage scaling
   ============================================================ */
(function(){
  const AB = window.AB;
  if (!AB) return;

  const stage = document.getElementById('stage');
  let scale = 1;

  function fit(){
    const vw = window.innerWidth || 1600;
    const vh = window.innerHeight || 900;
    scale = Math.min(vw / AB.C.W, vh / AB.C.H);
    stage.style.transform = 'scale(' + scale + ')';
  }

  window.addEventListener('resize', fit);
  window.addEventListener('orientationchange', fit);
  fit();

  // unlock audio on the very first real gesture
  function unlock(){
    AB.Audio.unlock();
    window.removeEventListener('pointerdown', unlock);
    window.removeEventListener('keydown', unlock);
  }
  window.addEventListener('pointerdown', unlock);
  window.addEventListener('keydown', unlock);

  AB.UI.init();
  AB.Engine.init();

  // HUD / DOM sync (engine has its own canvas loop)
  function tick(){
    AB.UI.tick();
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);

  // boot screen
  const boot = document.getElementById('boot');
  requestAnimationFrame(() => {
    setTimeout(() => {
      if (!boot) return;
      boot.classList.add('done');
      setTimeout(() => { if (boot.parentNode) boot.parentNode.removeChild(boot); }, 700);
    }, 420);
  });

  // handy for debugging from the console
  window.AIRBALL = {
    engine: AB.Engine,
    ui: AB.UI,
    get scale(){ return scale; }
  };
})();

