Implement:

```js
const q = new URLSearchParams(location.search);
const screen = q.get('screen');
const p1 = q.get('p1'), p2 = q.get('p2');
if (p1 || p2) AB.UI.setPicks([p1 || AB.DEFAULT_P1, p2 || AB.DEFAULT_P2]);
if (screen === 'select') AB.UI.showSelect();
else if (screen) {
  setTimeout(() => {
    AB.Engine.startMatch(AB.byId(p1||AB.DEFAULT_P1), AB.byId(p2||AB.DEFAULT_P2));
    if (screen==='pause') setTimeout(()=>AB.Engine.pause(), 1200);
    if (screen==='results') setTimeout(()=>{
      const E=AB.Engine;
      E.score=[28,24]; E.quarter=4;
      const s=[{pts:28,fga:19,fgm:12,dunks:3,steals:2,blocks:1,bestStreak:5},{pts:24,fga:21,fgm:10,dunks:1,steals:3,blocks:2,bestStreak:3}];
      E.players.forEach((p,i)=>p.stats=s[i]);
      E.gameOver();
    }, 1400);
  }, 250);
}
```
