14:   function ik2(sx, sy, tx, ty, l1, l2, preferDown){
15:     let dx = tx - sx, dy = ty - sy;
16:     let d = Math.hypot(dx, dy);
17:     const min = Math.abs(l1 - l2) + .001;
18:     const max = l1 + l2 - .001;
19:     if (d < min) d = min;
20:     if (d > max) d = max;
21:     const ux = dx / (Math.hypot(dx, dy) || 1), uy = dy / (Math.hypot(dx, dy) || 1);
22:     const a = (l1 * l1 - l2 * l2 + d * d) / (2 * d);
23:     const h = Math.sqrt(Math.max(0, l1 * l1 - a * a));
24:     const mx = sx + ux * a, my = sy + uy * a;
25:     const e1x = mx - uy * h, e1y = my + ux * h;
26:     const e2x = mx + uy * h, e2y = my - ux * h;
27:     let ex, ey;
28:     if (preferDown ? (e1y > e2y) : (e1y < e2y)) { ex = e1x; ey = e1y; }
29:     else { ex = e2x; ey = e2y; }
30:     return { ex, ey, hx: sx + ux * d, hy: sy + uy * d, d };
31:   }
