362:       P.bf = [Math.cos(ph) * stride, -.03 - Math.max(0, Math.sin(ph + Math.PI)) * .11];
363:       P.fh = [-.05 + Math.sin(ph) * .26, -.5 + Math.sin(ph) * .04];
364:       P.bh = [-.05 - Math.sin(ph) * .26, -.5 - Math.sin(ph) * .04];
365:       P.headTilt = .02;
366:     } else if (st === 'jump'){
367:       const k = U.clamp(p.jumpT * 2.4, 0, 1);
368:       P.crouch = .0;
369:       P.ff = [.11, -.4 - k * .1];
370:       P.bf = [-.13, -.34 - k * .08];
371:       P.fh = [.13, -.95];
372:       P.bh = [-.04, -.92];
373:       P.lean = .05;
374:       P.headTilt = -.05;
375:     } else if (st === 'charge'){
376:       const ch = U.clamp(p.chargePower, 0, 1);
377:       P.crouch = .036 + ch * .02;
378:       P.lean = -.04 + ch * .06;
379:       P.ff = [.11, -.03];
380:       P.bf = [-.12, -.03];
381:       P.fh = [.16, -.72 - ch * .41];
382:       P.bh = [.1, -.58];
383:       P.headTilt = -.02;
384:     } else if (st === 'release'){
385:       const k = U.clamp(p.stateT / .22, 0, 1);
386:       P.crouch = .0;
387:       P.lean = .04;
388:       P.ff = [.1, -.03];
389:       P.bf = [-.1, -.03];
390:       P.fh = [.14, -1.0 - Math.sin(k * Math.PI) * .08];
391:       P.bh = [-.03, -.9];
392:       P.headTilt = -.06;
393:       P.mouth = .3;
394:     } else if (st === 'dunk'){
395:       const k = p.dunk ? U.clamp(p.dunk.t / p.dunk.dur, 0, 1) : 0;
396:       P.crouch = 0;
397:       P.lean = .12;
398:       P.ff = [.16, -.34];
399:       P.bf = [-.2, -.24];
400:       P.fh = [.15, -1.06];
401:       P.bh = [.02, -1.0];
402:       P.headTilt = -.1;
403:       P.mouth = .7;
404:       P.rot = -.06;
405:     } else if (st === 'steal'){
406:       const k = U.clamp(p.stateT / .18, 0, 1);
407:       P.lean = .3;
408:       P.crouch = .06;
409:       P.ff = [.19, -.03];
410:       P.bf = [-.2, -.03];
411:       P.fh = [.3 * k + .12, -.58];
412:       P.bh = [-.05, -.45];
413:       P.headTilt = -.06;
414:     } else if (st === 'block'){
415:       P.lean = -.03;
416:       P.crouch = 0;
417:       P.ff = [.09, -.28];
418:       P.bf = [-.11, -.24];
419:       P.fh = [.12, -1.08];
420:       P.bh = [-.06, -1.02];
421:       P.headTilt = -.04;
422:     } else if (st === 'stumble'){
423:       const k = U.clamp(p.stateT / .35, 0, 1);
424:       P.lean = -.22 * (1 - k * .4);
425:       P.crouch = .05;
426:       P.ff = [.17, -.03];
427:       P.bf = [-.18, -.03];
428:       P.fh = [.02, -.75];
429:       P.bh = [-.2, -.7];
430:       P.headTilt = .15;
431:       P.mouth = .4;
432:     } else if (st === 'celebrate'){
433:       const b = Math.abs(Math.sin(p.stateT * 7));
434:       P.crouch = b * .05;
435:       P.lean = -.04;
436:       P.fh = [.16 + Math.sin(p.stateT * 5) * .04, -1.02];
437:       P.bh = [-.12, -1.0];
438:       P.ff = [.09, -.03 - b * .08];
439:       P.bf = [-.1, -.03 - b * .08];
440:       P.mouth = .6;
441:       P.headTilt = -.08;
442:     } else if (st === 'land'){
443:       P.crouch = .075;
444:       P.lean = .12;
445:       P.fh = [.18, -.36];
446:       P.bh = [-.08, -.38];
447:     } else {
448:       // idle / dribble
449:       const b = Math.sin(t * 2.1 + p.idx * 2) * .006;
450:       P.crouch = .014 + b;
451:       P.lean = .02 + Math.sin(t * 1.3 + p.idx) * .012;
452:       P.fh = [.16, -.44 + b * .5];
453:       P.bh = [-.005, -.42 - b * .4];
454:       P.ff = [.07, -.03];
455:       P.bf = [-.08, -.03];
456:       P.headTilt = Math.sin(t * 1.1 + p.idx) * .015;
457:     }
458: 
459:     // dribbling arm follows ball
460:     if (p.hasBall && (st === 'idle' || st === 'run' || st === 'land') && p.ballAnim){
461:       const H = C.PLAYER_H * p.data.body.h;
462:       const bx = ((p.ballAnim.x - p.x) * p.facing) / H;
463:       const by = (p.ballAnim.y - (C.FLOOR_Y - p.z)) / H;
464:       P.fh = [U.clamp(bx, -.02, .32), U.clamp(by, -.66, -.26)];
465:       P.bh = [.02, -.42];
466:       if (st === 'run'){
467:         P.fh[1] = U.clamp(by, -.72, -.3);
468:       }
469:     }
470:     return P;
471:   }
