473:   function easePose(cur, tgt, dt){
474:     const r = 20;
475:     for (const k in tgt){
476:       const tv = tgt[k];
477:       if (typeof tv === 'number'){
478:         cur[k] = cur[k] == null ? tv : U.damp(cur[k], tv, r, dt);
479:       } else {
480:         if (!cur[k]) cur[k] = tv.slice();
481:         cur[k][0] = U.damp(cur[k][0], tv[0], r, dt);
482:         cur[k][1] = U.damp(cur[k][1], tv[1], r, dt);
483:       }
484:     }
485:   }
