487:   Players.draw = function(ctx, p, t, dt){
488:     const d = p.data;
489:     const H = C.PLAYER_H * d.body.h;
490:     const s = H; // shorthand for local units
491:     if (!p.pose) p.pose = basePose();
492:     const tgt = targetPose(p, t);
493:     easePose(p.pose, tgt, Math.min(dt, .05));
494:     const po = p.pose;
495: 
496:     const px = p.x;
497:     const py = C.FLOOR_Y - (p.z || 0);
498:     const face = p.facing >= 0 ? 1 : -1;
499: 
500:     ctx.save();
501:     ctx.translate(px, py);
502:     ctx.scale(face, 1);
503: 
504:     if (p.onFire){
505:       const grd = ctx.createRadialGradient(0, -H * .5, 10, 0, -H * .5, H * .8);
506:       grd.addColorStop(0, 'rgba(255,150,40,.22)');
507:       grd.addColorStop(1, 'rgba(255,80,0,0)');
508:       ctx.fillStyle = grd;
509:       ctx.fillRect(-H * .8, -H * 1.5, H * 1.6, H * 1.5);
510:     }
511: 
512:     ctx.rotate(po.rot);
513: 
514:     const pelvisY = -.49 * H + po.crouch * H;
515:     const lean = po.lean;
516:     const hipF = [ .042 * H, pelvisY ];
517:     const hipB = [-.042 * H, pelvisY ];
518: 
519:     // shoulders (leaning around pelvis)
520:     const chestY = pelvisY - .285 * H;
521:     const shX = Math.sin(lean) * .285 * H;
522:     const shY = pelvisY - Math.cos(lean) * .285 * H;
523:     const shoulderF = [shX + .082 * H * d.body.shoulders, shY + .002 * H];
524:     const shoulderB = [shX - .086 * H * d.body.shoulders, shY + .004 * H];
525: 
526:     const thigh = .245 * H, shin = .215 * H;
527:     const armU = .19 * H, armF = .18 * H;
528: 
529:     // legs
530:     const footF = [po.ff[0] * H, po.ff[1] * H];
531:     const footB = [po.bf[0] * H, po.bf[1] * H];
532:     const legF = ik2(hipF[0], hipF[1], footF[0], footF[1], thigh, shin, false);
533:     const legB = ik2(hipB[0], hipB[1], footB[0], footB[1], thigh, shin, false);
534:     // force knee forward
535:     if (legF.ex < hipF[0] && legF.ey > hipF[1]) legF.ex = hipF[0] + (hipF[0] - legF.ex) * .2;
536:     if (legB.ex < hipB[0] && legB.ey > hipB[1]) legB.ex = hipB[0] + (hipB[0] - legB.ex) * .2;
537: 
538:     // arms targets (pose coordinates are relative to the feet)
539:     const armFrontT = [po.fh[0] * H, po.fh[1] * H];
540:     const armBackT = [po.bh[0] * H, po.bh[1] * H];
541:     const armFik = ik2(shoulderF[0], shoulderF[1], armFrontT[0], armFrontT[1], armU, armF, true);
542:     const armBik = ik2(shoulderB[0], shoulderB[1], armBackT[0], armBackT[1], armU, armF, true);
543: 
544:     const skin = d.skin, shade = d.skinShade, light = d.skinLight;
545: 
546:     /* ---- back arm ---- */
547:     limb(ctx, shoulderB[0], shoulderB[1], armBik.ex, armBik.ey, .038 * H, .032 * H, U.darken(skin, .1), shade, light);
548:     if (d.sleeve){
549:       limb(ctx, shoulderB[0], shoulderB[1], armBik.ex, armBik.ey, .039 * H, .033 * H, d.sleeve, U.darken(d.sleeve, .25), null);
550:     }
551:     limb(ctx, armBik.ex, armBik.ey, armBik.hx, armBik.hy, .031 * H, .025 * H, U.darken(skin, .06), shade, light);
552:     hand(ctx, armBik.hx, armBik.hy, .028 * H, U.darken(skin, .04), shade, null);
553: 
554:     /* ---- back leg ---- */
555:     limb(ctx, hipB[0], hipB[1], legB.ex, legB.ey, .06 * H, .042 * H, U.darken(skin, .12), shade, light);
556:     limb(ctx, legB.ex, legB.ey, legB.hx, legB.hy, .041 * H, .027 * H, U.darken(skin, .08), shade, light);
557:     shoe(ctx, legB.hx, legB.hy, Math.atan2(legB.hx - legB.ex, legB.hy - legB.ey) * .55, d, s, true);
558: 
559:     /* ---- torso ---- */
560:     ctx.save();
561:     ctx.translate(0, pelvisY);
562:     ctx.rotate(lean);
563:     const torsoTop = -.285 * H;
564:     const jc = d.colors;
565: 
566:     // body skin (torso)
567:     ctx.beginPath();
568:     ctx.moveTo(-.085 * H, .07 * H);
569:     ctx.bezierCurveTo(-.115 * H, -.09 * H, -.115 * H, -.21 * H, -.10 * H, torsoTop + .02 * H);
570:     ctx.bezierCurveTo(-.06 * H, torsoTop - .015 * H, .055 * H, torsoTop - .015 * H, .10 * H, torsoTop + .02 * H);
571:     ctx.bezierCurveTo(.12 * H, -.21 * H, .115 * H, -.09 * H, .085 * H, .07 * H);
572:     ctx.closePath();
573:     const torsoG = ctx.createLinearGradient(-.1 * H, 0, .1 * H, 0);
574:     torsoG.addColorStop(0, shade); torsoG.addColorStop(.55, skin); torsoG.addColorStop(1, light);
575:     ctx.fillStyle = torsoG; ctx.fill();
576: 
577:     // jersey
578:     ctx.beginPath();
579:     ctx.moveTo(-.095 * H, .05 * H);
580:     ctx.lineTo(-.105 * H, -.20 * H);
581:     ctx.bezierCurveTo(-.11 * H, torsoTop + .01 * H, -.085 * H, torsoTop - .01 * H, -.046 * H, torsoTop - .005 * H);
582:     ctx.quadraticCurveTo(-.02 * H, torsoTop + .045 * H, .015 * H, torsoTop + .04 * H);
583:     ctx.quadraticCurveTo(.055 * H, torsoTop + .035 * H, .075 * H, torsoTop - .002 * H);
584:     ctx.bezierCurveTo(.10 * H, torsoTop + .02 * H, .108 * H, -.19 * H, .098 * H, .05 * H);
585:     ctx.quadraticCurveTo(0, .075 * H, -.095 * H, .05 * H);
586:     ctx.closePath();
587:     const jg = ctx.createLinearGradient(-.1 * H, 0, .1 * H, 0);
588:     jg.addColorStop(0, U.darken(jc.jersey, .3));
589:     jg.addColorStop(.5, jc.jersey);
590:     jg.addColorStop(1, U.lighten(jc.jersey, .12));
591:     ctx.fillStyle = jg; ctx.fill();
592: 
593:     // jersey trim (side + neck)
594:     ctx.save();
595:     ctx.beginPath();
596:     ctx.moveTo(-.095 * H, .05 * H);
597:     ctx.lineTo(-.105 * H, -.20 * H);
598:     ctx.bezierCurveTo(-.11 * H, torsoTop + .01 * H, -.085 * H, torsoTop - .01 * H, -.046 * H, torsoTop - .005 * H);
599:     ctx.quadraticCurveTo(-.02 * H, torsoTop + .045 * H, .015 * H, torsoTop + .04 * H);
600:     ctx.quadraticCurveTo(.055 * H, torsoTop + .035 * H, .075 * H, torsoTop - .002 * H);
601:     ctx.bezierCurveTo(.10 * H, torsoTop + .02 * H, .108 * H, -.19 * H, .098 * H, .05 * H);
602:     ctx.quadraticCurveTo(0, .075 * H, -.095 * H, .05 * H);
603:     ctx.closePath();
604:     ctx.clip();
605:     ctx.fillStyle = jc.trim;
606:     ctx.globalAlpha = .9;
607:     ctx.fillRect(.062 * H, -.26 * H, .014 * H, .3 * H);
608:     ctx.globalAlpha = .55;
609:     ctx.fillRect(-.02 * H, torsoTop + .028 * H, .04 * H, .012 * H);
610:     // shading
611:     ctx.globalAlpha = .25;
612:     ctx.fillStyle = '#000';
613:     ctx.fillRect(-.105 * H, -.26 * H, .028 * H, .32 * H);
614:     ctx.restore();
615: 
616:     // number
617:     ctx.save();
618:     ctx.translate(.008 * H, -.115 * H);
619:     ctx.scale(face, 1);
620:     ctx.font = `700 ${.125 * H}px "Bahnschrift","Arial Narrow",sans-serif`;
621:     ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
622:     ctx.fillStyle = 'rgba(0,0,0,.32)';
623:     ctx.fillText(d.num, 1.5, 1.5);
624:     ctx.fillStyle = jc.text;
625:     ctx.fillText(d.num, 0, 0);
626:     ctx.restore();
627: 
628:     // shorts
629:     ctx.beginPath();
630:     ctx.moveTo(-.098 * H, .045 * H);
631:     ctx.lineTo(-.112 * H, .16 * H);
632:     ctx.quadraticCurveTo(-.10 * H, .20 * H, -.065 * H, .2 * H);
633:     ctx.lineTo(-.02 * H, .19 * H);
634:     ctx.lineTo(0, .125 * H);
635:     ctx.lineTo(.02 * H, .19 * H);
636:     ctx.lineTo(.068 * H, .2 * H);
637:     ctx.quadraticCurveTo(.108 * H, .20 * H, .115 * H, .16 * H);
638:     ctx.lineTo(.098 * H, .045 * H);
639:     ctx.closePath();
640:     const sg = ctx.createLinearGradient(-.11 * H, 0, .11 * H, 0);
641:     sg.addColorStop(0, U.darken(jc.jersey, .34));
642:     sg.addColorStop(.55, jc.jersey);
643:     sg.addColorStop(1, U.lighten(jc.jersey, .08));
644:     ctx.fillStyle = sg; ctx.fill();
645:     // short trim
646:     ctx.strokeStyle = jc.trim;
647:     ctx.lineWidth = .012 * H;
648:     ctx.globalAlpha = .9;
649:     ctx.beginPath();
650:     ctx.moveTo(.07 * H, .055 * H);
651:     ctx.lineTo(.085 * H, .185 * H);
652:     ctx.stroke();
653:     ctx.beginPath();
654:     ctx.moveTo(-.075 * H, .058 * H);
655:     ctx.lineTo(-.09 * H, .185 * H);
656:     ctx.stroke();
657:     ctx.globalAlpha = 1;
658:     // waistband
659:     ctx.fillStyle = 'rgba(0,0,0,.22)';
660:     ctx.fillRect(-.098 * H, .04 * H, .196 * H, .022 * H);
661:     ctx.restore();
662: 
663:     /* ---- front leg ---- */
664:     limb(ctx, hipF[0], hipF[1], legF.ex, legF.ey, .062 * H, .044 * H, skin, shade, light);
665:     // knee pad hint / leg shading
666:     limb(ctx, legF.ex, legF.ey, legF.hx, legF.hy, .042 * H, .028 * H, skin, shade, light);
667:     if (d.body.build > 1.05){
668:       // muscular calf highlight
669:       ctx.save();
670:       ctx.globalAlpha = .18;
671:       U.ellipse(ctx, (legF.ex + legF.hx) / 2 - .012 * H, (legF.ey + legF.hy) / 2, .022 * H, .05 * H);
672:       ctx.fillStyle = light; ctx.fill();
673:       ctx.restore();
674:     }
675:     shoe(ctx, legF.hx, legF.hy, Math.atan2(legF.hx - legF.ex, legF.hy - legF.ey) * .55, d, s, false);
676: 
677:     /* ---- head + neck ---- */
678:     const neckX = shX + .012 * H;
679:     const neckY = shY - .012 * H;
680:     const headCx = shX + .018 * H + Math.sin(po.headTilt) * .02 * H;
681:     const headCy = shY - .085 * H;
682:     sideHead(ctx, headCx, headCy, H, d, { tilt: po.headTilt + lean * .3, hairKick: p.moveAmt || 0 });
683: 
684:     /* ---- front arm ---- */
685:     limb(ctx, shoulderF[0], shoulderF[1], armFik.ex, armFik.ey, .042 * H, .034 * H, skin, shade, light);
686:     if (d.sleeve){
687:       limb(ctx, shoulderF[0], shoulderF[1], armFik.ex, armFik.ey, .043 * H, .035 * H, d.sleeve, U.darken(d.sleeve, .22), null);
688:     }
689:     limb(ctx, armFik.ex, armFik.ey, armFik.hx, armFik.hy, .033 * H, .026 * H, skin, shade, light);
690:     // shooting hand: wristband
691:     hand(ctx, armFik.hx, armFik.hy, .029 * H, skin, shade, d.wrist);
692: 
693:     ctx.restore();
694:   };
