699:   function frontHead(ctx, cx, cy, R, d, opt = {}){
700:     const skin = d.skin, shade = d.skinShade, light = d.skinLight;
701:     const rx = R, ry = R * 1.24;
702:     ctx.save();
703:     ctx.translate(cx, cy);
704: 
705:     // ears
706:     for (const s of [-1, 1]){
707:       ctx.beginPath();
708:       ctx.ellipse(s * rx * .96, ry * .12, rx * .19, ry * .27, s * .1, 0, TAU);
709:       ctx.fillStyle = U.darken(skin, .04); ctx.fill();
710:       ctx.strokeStyle = U.rgba(shade, .5); ctx.lineWidth = 1.3; ctx.stroke();
711:       ctx.beginPath();
712:       ctx.ellipse(s * rx * .97, ry * .12, rx * .1, ry * .16, s * .1, 0, TAU);
713:       ctx.strokeStyle = U.rgba(shade, .5); ctx.lineWidth = 1.1; ctx.stroke();
714:     }
715: 
716:     // skull
717:     ctx.beginPath();
718:     ctx.moveTo(0, -ry * 1.02);
719:     ctx.bezierCurveTo(rx * .62, -ry * 1.02, rx * 1.0, -ry * .64, rx * 1.0, -ry * .1);
720:     ctx.bezierCurveTo(rx * 1.0, ry * .3, rx * .86, ry * .52, rx * .62, ry * .72);
721:     ctx.bezierCurveTo(rx * .42, ry * .92, rx * .2, ry * 1.0, 0, ry * 1.0);
722:     ctx.bezierCurveTo(-rx * .3, ry * 1.0, -rx * .66, ry * .86, -rx * .84, ry * .58);
723:     ctx.bezierCurveTo(-rx * 1.0, ry * .3, -rx * 1.0, -ry * .15, -rx * .99, -ry * .2);
724:     ctx.bezierCurveTo(-rx * .97, -ry * .8, -rx * .55, -ry * 1.02, 0, -ry * 1.02);
725:     ctx.closePath();
726:     const hg = ctx.createRadialGradient(-rx * .3, -ry * .35, rx * .1, 0, 0, rx * 1.5);
727:     hg.addColorStop(0, light);
728:     hg.addColorStop(.45, skin);
729:     hg.addColorStop(1, shade);
730:     ctx.fillStyle = hg;
731:     ctx.fill();
732:     ctx.strokeStyle = 'rgba(30,16,8,.22)';
733:     ctx.lineWidth = 1.4;
734:     ctx.stroke();
735: 
736:     // cheek / jaw shading
737:     ctx.save();
738:     ctx.globalAlpha = .22;
739:     ctx.fillStyle = shade;
740:     ctx.beginPath();
741:     ctx.ellipse(-rx * .55, ry * .35, rx * .3, ry * .45, .2, 0, TAU);
742:     ctx.fill();
743:     ctx.beginPath();
744:     ctx.ellipse(rx * .55, ry * .38, rx * .26, ry * .4, -.2, 0, TAU);
745:     ctx.fill();
746:     ctx.restore();
747: 
748:     // ears inner
749:     // eyes
750:     const eyeY = -ry * .12, eyeX = rx * .4;
751:     for (const s of [-1, 1]){
752:       ctx.save();
753:       // sclera
754:       ctx.beginPath();
755:       ctx.ellipse(s * eyeX, eyeY, rx * .23, ry * .13, s * .04, 0, TAU);
756:       ctx.fillStyle = '#f6efe6'; ctx.fill();
757:       ctx.strokeStyle = 'rgba(40,24,12,.5)'; ctx.lineWidth = 1; ctx.stroke();
758:       // iris
759:       ctx.beginPath();
760:       ctx.arc(s * eyeX + s * rx * .02, eyeY + ry * .01, rx * .115, 0, TAU);
761:       ctx.fillStyle = d.eyes || '#2a1a10'; ctx.fill();
762:       ctx.beginPath();
763:       ctx.arc(s * eyeX + s * rx * .02, eyeY + ry * .01, rx * .055, 0, TAU);
764:       ctx.fillStyle = '#0a0705'; ctx.fill();
765:       ctx.beginPath();
766:       ctx.arc(s * eyeX + s * rx * .05, eyeY - ry * .025, rx * .028, 0, TAU);
767:       ctx.fillStyle = 'rgba(255,255,255,.9)'; ctx.fill();
768:       // upper lid
769:       ctx.beginPath();
770:       ctx.moveTo(s * eyeX - rx * .24, eyeY - ry * .03);
771:       ctx.quadraticCurveTo(s * eyeX, eyeY - ry * .16, s * eyeX + rx * .24, eyeY - ry * .03);
772:       ctx.strokeStyle = 'rgba(35,20,10,.8)'; ctx.lineWidth = 2.2; ctx.stroke();
773:       // brows
774:       ctx.beginPath();
775:       const by = eyeY - ry * .27;
776:       ctx.moveTo(s * eyeX - rx * .24, by + (s < 0 ? ry * .02 : 0));
777:       ctx.quadraticCurveTo(s * eyeX, by - ry * .11, s * eyeX + rx * .26, by + (s > 0 ? ry * .02 : 0));
778:       ctx.strokeStyle = d.brows || '#181210';
779:       ctx.lineWidth = rx * .11;
780:       ctx.lineCap = 'round';
781:       ctx.stroke();
782:       ctx.restore();
783:     }
784: 
785:     // nose
786:     ctx.save();
787:     ctx.globalAlpha = .5;
788:     ctx.strokeStyle = shade;
789:     ctx.lineWidth = 2;
790:     ctx.beginPath();
791:     ctx.moveTo(rx * .04, eyeY + ry * .12);
792:     ctx.quadraticCurveTo(-rx * .06, ry * .28, -rx * .11, ry * .31);
793:     ctx.stroke();
794:     ctx.globalAlpha = .9;
795:     ctx.fillStyle = U.rgba(shade, .85);
796:     ctx.beginPath(); ctx.ellipse(-rx * .1, ry * .32, rx * .045, ry * .022, .1, 0, TAU); ctx.fill();
797:     ctx.beginPath(); ctx.ellipse(rx * .1, ry * .32, rx * .045, ry * .022, -.1, 0, TAU); ctx.fill();
798:     // highlight nose bridge
799:     ctx.globalAlpha = .35;
800:     ctx.fillStyle = light;
801:     ctx.beginPath(); ctx.ellipse(rx * .01, ry * .08, rx * .055, ry * .17, .05, 0, TAU); ctx.fill();
802:     ctx.restore();
803: 
804:     // mouth
805:     const my = ry * .55;
806:     ctx.beginPath();
807:     ctx.moveTo(-rx * .22, my);
808:     ctx.quadraticCurveTo(0, my + (opt.mouth || 0) * ry * .09 - ry * .015, rx * .22, my);
809:     ctx.quadraticCurveTo(0, my + ry * .085, -rx * .22, my);
810:     ctx.fillStyle = U.darken(skin, .22); ctx.fill();
811:     ctx.strokeStyle = 'rgba(60,28,18,.65)'; ctx.lineWidth = 1.4;
812:     ctx.beginPath();
813:     ctx.moveTo(-rx * .22, my);
814:     ctx.quadraticCurveTo(0, my + .012 * ry, rx * .22, my);
815:     ctx.stroke();
816:     ctx.beginPath();
817:     ctx.moveTo(-rx * .15, my - ry * .03);
818:     ctx.quadraticCurveTo(0, my - ry * .05, rx * .15, my - ry * .03);
819:     ctx.strokeStyle = U.rgba(light, .35); ctx.lineWidth = 1.2; ctx.stroke();
820: 
821:     // beard
822:     if (d.facial !== 'none'){
823:       const bc = d.beard || '#1c1410';
824:       ctx.save();
825:       if (d.facial === 'stubble'){
826:         ctx.globalAlpha = .26;
827:         ctx.fillStyle = bc;
828:         ctx.beginPath();
829:         ctx.moveTo(-rx * .86, ry * .2);
830:         ctx.bezierCurveTo(-rx * .9, ry * .8, -rx * .5, ry * 1.0, 0, ry * 1.0);
831:         ctx.bezierCurveTo(rx * .5, ry * 1.0, rx * .9, ry * .8, rx * .86, ry * .2);
832:         ctx.bezierCurveTo(rx * .7, ry * .6, rx * .4, ry * .68, 0, ry * .68);
833:         ctx.bezierCurveTo(-rx * .4, ry * .68, -rx * .7, ry * .6, -rx * .86, ry * .2);
834:         ctx.closePath(); ctx.fill();
835:         ctx.fillStyle = bc;
836:         ctx.beginPath(); ctx.ellipse(0, my + ry * .03, rx * .28, ry * .05, 0, 0, TAU); ctx.fill();
837:       } else if (d.facial === 'goatee'){
838:         ctx.globalAlpha = .94;
839:         ctx.fillStyle = bc;
840:         ctx.beginPath();
841:         ctx.ellipse(0, ry * .78, rx * .34, ry * .2, 0, 0, TAU);
842:         ctx.fill();
843:         ctx.beginPath();
844:         ctx.ellipse(0, my + ry * .01, rx * .26, ry * .055, 0, 0, TAU);
845:         ctx.fill();
846:         // jaw line stubble
847:         ctx.globalAlpha = .3;
848:         ctx.beginPath();
849:         ctx.moveTo(-rx * .8, ry * .32);
850:         ctx.quadraticCurveTo(0, ry * .92, rx * .8, ry * .32);
851:         ctx.lineTo(rx * .72, ry * .24);
852:         ctx.quadraticCurveTo(0, ry * .78, -rx * .72, ry * .24);
853:         ctx.closePath(); ctx.fill();
854:       } else {
855:         ctx.globalAlpha = .95;
856:         ctx.fillStyle = bc;
857:         ctx.beginPath();
858:         ctx.moveTo(-rx * .9, ry * .06);
859:         ctx.bezierCurveTo(-rx * .93, ry * .62, -rx * .7, ry * .96, 0, ry * 1.0);
860:         ctx.bezierCurveTo(rx * .7, ry * .96, rx * .93, ry * .62, rx * .9, ry * .06);
861:         ctx.bezierCurveTo(rx * .72, ry * .42, rx * .42, ry * .5, 0, ry * .5);
862:         ctx.bezierCurveTo(-rx * .42, ry * .5, -rx * .72, ry * .42, -rx * .9, ry * .06);
863:         ctx.closePath(); ctx.fill();
864:         // mouth hole
865:         ctx.globalAlpha = .92;
866:         ctx.fillStyle = U.darken(skin, .28);
867:         ctx.beginPath(); ctx.ellipse(0, my, rx * .24, ry * .055, 0, 0, TAU); ctx.fill();
868:         ctx.fillStyle = bc;
869:         ctx.beginPath();
870:         ctx.ellipse(0, my - ry * .045, rx * .25, ry * .05, 0, 0, TAU);
871:         ctx.fill();
872:       }
873:       ctx.restore();
874:     }
875: 
876:     // hair
877:     frontHair(ctx, rx, ry, d);
878: 
879:     // headband
880:     if (d.headband){
881:       ctx.save();
882:       ctx.beginPath();
883:       ctx.moveTo(-rx * .99, -ry * .38);
884:       ctx.quadraticCurveTo(0, -ry * .52, rx * .99, -ry * .38);
885:       ctx.lineTo(rx * .98, -ry * .22);
886:       ctx.quadraticCurveTo(0, -ry * .34, -rx * .98, -ry * .22);
887:       ctx.closePath();
888:       ctx.fillStyle = d.headband;
889:       ctx.fill();
890:       ctx.strokeStyle = 'rgba(255,255,255,.25)'; ctx.lineWidth = 1.2;
891:       ctx.beginPath();
892:       ctx.moveTo(-rx * .97, -ry * .34);
893:       ctx.quadraticCurveTo(0, -ry * .47, rx * .97, -ry * .34);
894:       ctx.stroke();
895:       ctx.restore();
896:     }
897: 
898:     // rim light
899:     ctx.save();
900:     ctx.globalCompositeOperation = 'screen';
901:     const rl = ctx.createLinearGradient(-rx, 0, rx * .2, 0);
902:     rl.addColorStop(0, 'rgba(140,190,255,.35)');
903:     rl.addColorStop(1, 'rgba(255,190,120,0)');
904:     ctx.fillStyle = rl;
905:     ctx.beginPath();
906:     ctx.ellipse(-rx * .82, -ry * .1, rx * .2, ry * .8, 0, 0, TAU);
907:     ctx.fill();
908:     ctx.restore();
909: 
910:     // forehead shine
911:     ctx.save();
912:     ctx.globalAlpha = .18;
913:     ctx.fillStyle = '#fff';
914:     ctx.beginPath();
915:     ctx.ellipse(-rx * .3, -ry * .5, rx * .3, ry * .16, -.3, 0, TAU);
916:     ctx.fill();
917:     ctx.restore();
918: 
919:     ctx.restore();
920:   }
