922:   function frontHair(ctx, rx, ry, d){
923:     const st = d.hair.style, col = d.hair.color, hi = d.hair.light;
924:     if (st === 'bald'){
925:       ctx.save();
926:       ctx.globalAlpha = .25;
927:       ctx.fillStyle = '#fff';
928:       ctx.beginPath();
929:       ctx.ellipse(-rx * .3, -ry * .82, rx * .28, ry * .1, -.3, 0, TAU);
930:       ctx.fill();
931:       ctx.restore();
932:       return;
933:     }
934:     ctx.save();
935:     const capPath = (line) => {
936:       ctx.beginPath();
937:       ctx.moveTo(-rx * 1.0, -ry * .22);
938:       ctx.bezierCurveTo(-rx * 1.0, -ry * .92, -rx * .58, -ry * 1.07, 0, -ry * 1.07);
939:       ctx.bezierCurveTo(rx * .6, -ry * 1.07, rx * 1.0, -ry * .9, rx * 1.0, -ry * .2);
940:       ctx.bezierCurveTo(rx * .8, -ry * .34, rx * .55, line, 0, line);
941:       ctx.bezierCurveTo(-rx * .55, line, -rx * .8, -ry * .36, -rx * 1.0, -ry * .22);
942:       ctx.closePath();
943:     };
944:     if (st === 'afro'){
945:       ctx.fillStyle = col;
946:       ctx.beginPath();
947:       ctx.ellipse(0, -ry * .78, rx * 1.18, ry * .58, 0, 0, TAU);
948:       ctx.fill();
949:       ctx.fillStyle = hi;
950:       ctx.globalAlpha = .4;
951:       ctx.beginPath();
952:       ctx.ellipse(-rx * .25, -ry * .98, rx * .55, ry * .2, -.1, 0, TAU);
953:       ctx.fill();
954:       ctx.restore();
955:       return;
956:     }
957:     if (st === 'curly'){
958:       ctx.fillStyle = col;
959:       ctx.beginPath();
960:       ctx.ellipse(0, -ry * .74, rx * 1.06, ry * .48, 0, 0, TAU);
961:       ctx.fill();
962:       for (let i = 0; i < 16; i++){
963:         const a = Math.PI + i * (Math.PI / 15);
964:         const rr = rx * (.86 + (i % 3) * .06);
965:         ctx.fillStyle = i % 2 ? hi : col;
966:         ctx.beginPath();
967:         ctx.arc(Math.cos(a) * rr, -ry * .48 + Math.sin(a) * ry * .38, rx * .14, 0, TAU);
968:         ctx.fill();
969:       }
970:       ctx.restore();
971:       return;
972:     }
973:     capPath(-ry * .36);
974:     const g = ctx.createLinearGradient(0, -ry * 1.05, 0, -ry * .2);
975:     g.addColorStop(0, hi); g.addColorStop(.45, col); g.addColorStop(1, U.darken(col, .25));
976:     ctx.fillStyle = g;
977:     ctx.fill();
978: 
979:     // hairline details
980:     if (st === 'short'){
981:       ctx.strokeStyle = U.rgba(hi, .5);
982:       ctx.lineWidth = 1.4;
983:       for (let i = -3; i <= 3; i++){
984:         ctx.beginPath();
985:         ctx.moveTo(i * rx * .22, -ry * .98);
986:         ctx.quadraticCurveTo(i * rx * .25, -ry * .66, i * rx * .2, -ry * .4);
987:         ctx.stroke();
988:       }
989:     }
990:     if (st === 'buzz' || st === 'fade'){
991:       // sharper temples
992:       ctx.fillStyle = U.darken(col, .4);
993:       ctx.globalAlpha = .7;
994:       ctx.beginPath();
995:       ctx.moveTo(-rx, -ry * .2); ctx.lineTo(-rx * .82, -ry * .55); ctx.lineTo(-rx * .9, -ry * .18);
996:       ctx.closePath(); ctx.fill();
997:       ctx.beginPath();
998:       ctx.moveTo(rx, -ry * .2); ctx.lineTo(rx * .82, -ry * .55); ctx.lineTo(rx * .9, -ry * .18);
999:       ctx.closePath(); ctx.fill();
1000:     }
1001:     if (st === 'braids'){
1002:       ctx.strokeStyle = U.rgba(hi, .55);
1003:       ctx.lineWidth = 1.6;
1004:       for (let i = -4; i <= 4; i++){
1005:         ctx.beginPath();
1006:         ctx.moveTo(i * rx * .19, -ry * 1.03);
1007:         ctx.quadraticCurveTo(i * rx * .23, -ry * .74, i * rx * .18, -ry * .44);
1008:         ctx.stroke();
1009:       }
1010:     }
1011:     if (st === 'fade'){
1012:       ctx.globalAlpha = .5;
1013:       ctx.fillStyle = U.darken(col, .15);
1014:       ctx.beginPath();
1015:       ctx.ellipse(0, -ry * .22, rx * 1.0, ry * .13, 0, 0, TAU);
1016:       ctx.fill();
1017:     }
1018:     ctx.restore();
1019:   }
