1024:   Players.drawPortrait = function(ctx, d, W, H, opt = {}){
1025:     const bg = opt.bg !== false;
1026:     const R = opt.R || W * .195;
1027:     const cx = opt.cx != null ? opt.cx : W / 2;
1028:     const cy = opt.cy != null ? opt.cy : H * .42;
1029:     const bottom = H + 8;
1030:     const jc = d.colors;
1031:     ctx.clearRect(0, 0, W, H);
1032: 
1033:     if (bg){
1034:       // card background
1035:       const bgG = ctx.createLinearGradient(0, 0, W, H);
1036:       bgG.addColorStop(0, U.darken(jc.primary, .62));
1037:       bgG.addColorStop(.45, U.darken(jc.primary, .35));
1038:       bgG.addColorStop(1, '#05070c');
1039:       ctx.fillStyle = bgG;
1040:       ctx.fillRect(0, 0, W, H);
1041: 
1042:       // team colour beams
1043:       ctx.save();
1044:       ctx.globalAlpha = .5;
1045:       ctx.translate(cx, cy);
1046:       ctx.rotate(-.3);
1047:       for (let i = -2; i <= 2; i++){
1048:         const g = ctx.createLinearGradient(i * W * .2, -H, i * W * .2, H);
1049:         g.addColorStop(0, U.rgba(jc.secondary, .14));
1050:         g.addColorStop(1, U.rgba(jc.secondary, 0));
1051:         ctx.fillStyle = g;
1052:         ctx.fillRect(i * W * .2 - W * .04, -H, W * .08, H * 2);
1053:       }
1054:       ctx.restore();
1055: 
1056:       // spotlight behind head
1057:       const sp = ctx.createRadialGradient(cx, cy - R * .25, R * .1, cx, cy, R * 3.2);
1058:       sp.addColorStop(0, U.rgba(jc.secondary, .26));
1059:       sp.addColorStop(.5, U.rgba(jc.primary, .16));
1060:       sp.addColorStop(1, 'rgba(0,0,0,0)');
1061:       ctx.fillStyle = sp;
1062:       ctx.fillRect(0, 0, W, H);
1063: 
1064:       // halo ring
1065:       ctx.save();
1066:       ctx.globalAlpha = .18;
1067:       ctx.strokeStyle = jc.secondary;
1068:       ctx.lineWidth = Math.max(1, W * .0035);
1069:       ctx.beginPath(); ctx.arc(cx, cy - R * .1, R * 1.75, 0, TAU); ctx.stroke();
1070:       ctx.globalAlpha = .09;
1071:       ctx.beginPath(); ctx.arc(cx, cy - R * .1, R * 2.15, 0, TAU); ctx.stroke();
1072:       ctx.restore();
1073: 
1074:       // ghost number
1075:       ctx.save();
1076:       ctx.globalAlpha = .1;
1077:       ctx.fillStyle = '#fff';
1078:       ctx.font = `700 ${H * .55}px "Bahnschrift","Arial Narrow",sans-serif`;
1079:       ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
1080:       ctx.fillText(d.num, W * .84, H * .36);
1081:       ctx.restore();
1082: 
1083:       // grid / texture
1084:       ctx.save();
1085:       ctx.globalAlpha = .16;
1086:       ctx.strokeStyle = 'rgba(255,255,255,.06)';
1087:       ctx.lineWidth = 1;
1088:       for (let x = 0; x < W; x += W * .07){ ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }
1089:       ctx.restore();
1090:     }
1091: 
1092:     /* body / shoulders */
1093:     const shY = cy + R * 1.42;
1094:     const shW = R * 2.15;
1095:     const skin = d.skin, shade = d.skinShade, light = d.skinLight;
1096: 
1097:     // neck
1098:     const neckW = R * .56;
1099:     ctx.beginPath();
1100:     ctx.moveTo(cx - neckW * .5, cy + R * .78);
1101:     ctx.bezierCurveTo(cx - neckW * .48, shY - R * .2, cx - neckW * .6, shY - R * .05, cx - neckW * .7, shY + R * .12);
1102:     ctx.lineTo(cx + neckW * .7, shY + R * .12);
1103:     ctx.bezierCurveTo(cx + neckW * .6, shY - R * .05, cx + neckW * .48, shY - R * .2, cx + neckW * .5, cy + R * .78);
1104:     ctx.closePath();
1105:     ctx.fillStyle = skin;
1106:     ctx.fill();
1107:     // neck shadow
1108:     ctx.save();
1109:     ctx.globalAlpha = .35;
1110:     ctx.fillStyle = shade;
1111:     ctx.beginPath();
1112:     ctx.ellipse(cx, cy + R * 1.05, neckW * .56, R * .22, 0, 0, TAU);
1113:     ctx.fill();
1114:     ctx.restore();
1115: 
1116:     // jersey body
1117:     ctx.beginPath();
1118:     ctx.moveTo(cx - shW * .92, bottom);
1119:     ctx.lineTo(cx - shW * .98, shY + R * .28);
1120:     ctx.bezierCurveTo(cx - shW * .96, shY - R * .1, cx - shW * .68, shY - R * .22, cx - neckW * .8, shY - R * .08);
1121:     ctx.quadraticCurveTo(cx, shY + R * .24, cx + neckW * .8, shY - R * .08);
1122:     ctx.bezierCurveTo(cx + shW * .68, shY - R * .22, cx + shW * .96, shY - R * .1, cx + shW * .98, shY + R * .28);
1123:     ctx.lineTo(cx + shW * .92, bottom);
1124:     ctx.closePath();
1125:     const jg = ctx.createLinearGradient(cx - shW, 0, cx + shW, 0);
1126:     jg.addColorStop(0, U.darken(jc.jersey, .35));
1127:     jg.addColorStop(.35, jc.jersey);
1128:     jg.addColorStop(.62, U.lighten(jc.jersey, .06));
1129:     jg.addColorStop(1, U.darken(jc.jersey, .4));
1130:     ctx.fillStyle = jg;
1131:     ctx.fill();
1132: 
1133:     // jersey shoulder shading + rim light
1134:     ctx.save();
1135:     ctx.beginPath();
1136:     ctx.moveTo(cx - shW * .92, bottom);
1137:     ctx.lineTo(cx - shW * .98, shY + R * .28);
1138:     ctx.bezierCurveTo(cx - shW * .96, shY - R * .1, cx - shW * .68, shY - R * .22, cx - neckW * .8, shY - R * .08);
1139:     ctx.quadraticCurveTo(cx, shY + R * .24, cx + neckW * .8, shY - R * .08);
1140:     ctx.bezierCurveTo(cx + shW * .68, shY - R * .22, cx + shW * .96, shY - R * .1, cx + shW * .98, shY + R * .28);
1141:     ctx.lineTo(cx + shW * .92, bottom);
1142:     ctx.closePath();
1143:     ctx.clip();
1144:     // armhole shadows
1145:     ctx.globalAlpha = .4;
1146:     ctx.fillStyle = '#000';
1147:     ctx.beginPath(); ctx.ellipse(cx - shW * .84, shY + R * .35, R * .34, R * .8, .25, 0, TAU); ctx.fill();
1148:     ctx.beginPath(); ctx.ellipse(cx + shW * .84, shY + R * .35, R * .34, R * .8, -.25, 0, TAU); ctx.fill();
1149:     // sheen
1150:     ctx.globalAlpha = .12;
1151:     ctx.fillStyle = '#fff';
1152:     ctx.beginPath();
1153:     ctx.ellipse(cx - shW * .35, shY + R * .55, R * .5, R * 1.1, .25, 0, TAU);
1154:     ctx.fill();
1155:     ctx.restore();
1156: 
1157:     // neckline trim
1158:     ctx.beginPath();
1159:     ctx.moveTo(cx - neckW * .86, shY - R * .06);
1160:     ctx.quadraticCurveTo(cx, shY + R * .3, cx + neckW * .86, shY - R * .06);
1161:     ctx.strokeStyle = jc.trim;
1162:     ctx.lineWidth = Math.max(3, R * .09);
1163:     ctx.lineCap = 'round';
1164:     ctx.stroke();
1165:     ctx.strokeStyle = 'rgba(0,0,0,.25)';
1166:     ctx.lineWidth = Math.max(1, R * .02);
1167:     ctx.stroke();
1168: 
1169:     // armhole trim
1170:     for (const s of [-1, 1]){
1171:       ctx.beginPath();
1172:       ctx.moveTo(cx + s * shW * .82, shY - R * .02);
1173:       ctx.quadraticCurveTo(cx + s * shW * .98, shY + R * .4, cx + s * shW * .86, shY + R * .9);
1174:       ctx.strokeStyle = jc.trim;
1175:       ctx.lineWidth = Math.max(2.6, R * .075);
1176:       ctx.stroke();
1177:     }
1178: 
1179:     // chest number
1180:     ctx.save();
1181:     ctx.font = `700 ${R * 1.22}px "Bahnschrift","Arial Narrow",sans-serif`;
1182:     ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
1183:     ctx.fillStyle = 'rgba(0,0,0,.28)';
1184:     ctx.fillText(d.num, cx + 2, shY + R * 1.32 + 2);
1185:     ctx.fillStyle = jc.text;
1186:     ctx.fillText(d.num, cx, shY + R * 1.3);
1187:     ctx.restore();
1188: 
1189:     // small team wordmark
1190:     ctx.save();
1191:     ctx.globalAlpha = .85;
1192:     ctx.font = `700 ${R * .22}px "Bahnschrift","Arial Narrow",sans-serif`;
1193:     ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
1194:     ctx.fillStyle = jc.trim;
1195:     ctx.fillText(d.abbr, cx, shY + R * 1.95);
1196:     ctx.restore();
1197: 
1198:     // head
1199:     frontHead(ctx, cx, cy, R, d, { mouth: .25 });
1200: 
1201:     // vignette
1202:     if (bg){
1203:       const vg = ctx.createRadialGradient(W * .5, H * .45, W * .2, W * .5, H * .5, W * .78);
1204:       vg.addColorStop(0, 'rgba(0,0,0,0)');
1205:       vg.addColorStop(1, 'rgba(0,0,0,.55)');
1206:       ctx.fillStyle = vg;
1207:       ctx.fillRect(0, 0, W, H);
1208:       const bot = ctx.createLinearGradient(0, H * .7, 0, H);
1209:       bot.addColorStop(0, 'rgba(3,6,11,0)');
1210:       bot.addColorStop(1, 'rgba(3,6,11,.92)');
1211:       ctx.fillStyle = bot;
1212:       ctx.fillRect(0, H * .7, W, H * .3);
1213:     }
1214:   };
