  const step = (n, dt=1/60) => { for (let i=0;i<n;i++){ E.update(dt); E.pressed={}; E.released={}; } };
  function setup(x, shooter){
    E.paused=false; E.mode='match'; E.phase='live'; E.countdownT=0; E.clock=60; E.shotClock=14; E.deadT=0; E.deadNext=null; E.awaitShot=false; E.score=[0,0];
    p1.stats={pts:0,fga:0,fgm:0,dunks:0,steals:0,blocks:0,bestStreak:0};
    p2.stats={pts:0,fga:0,fgm:0,dunks:0,steals:0,blocks:0,bestStreak:0};
    for (const p of [p1,p2]){ p.dunk=null; p.charging=false; p.state='idle'; p.z=0; p.vz=0; p.grounded=true; p.hasBall=false; p.chargeT=0; p.chargePower=0; }
    p1.x=x; p1.facing=p1.attackDir;
