const script = `(() => {
  const E = AB.Engine;
  const p1=E.players[0], p2=E.players[1];
  const step = (n, dt=1/60) => { for (let i=0;i<n;i++){ E.update(dt); E.pressed={}; E.released={}; } };
  function setup(x, shooter, chargeFrames){
    E.paused=false; E.mode='match'; E.phase='live'; E.countdownT=0; E.clock=60; E.shotClock=14; E.deadT=0; E.deadNext=null; E.awaitShot=false; E.score=[0,0];
    p1.stats={pts:0,fga:0,fgm:0,dunks:0,steals:0,blocks:0,bestStreak:0};
    p2.stats={pts:0,fga:0,fgm:0,dunks:0,steals:0,blocks:0,bestStreak:0};
    for (const p of [p1,p2]){ p.dunk=null; p.charging=false; p.state='idle'; p.z=0; p.vz=0; p.grounded=true; p.hasBall=false; p.chargeT=0; p.chargePower=0; p.stumbleT=0; p.graceT=0; p.pickupLock=0; }
    p1.x=x; p1.facing=p1.attackDir;
    p2.x=shooter===p1?300:1300; p2.z=0; p2.grounded=true;
    E.ball.state='held'; E.ball.catchable=false; E.ball.scoreable=false; E.ball.owner=null;
    E.giveBall(shooter);
    const act=shooter.idx===0?'KeyF':'KeyL';
    E.keys[act]=true; E.pressed[act]=true; step(1); E.keys[act]=false;
    step(chargeFrames);
    E.released[act]=true; step(1);
    step(170);
    return {score:E.score.slice(), fga:shooter.stats.fga, fgm:shooter.stats.fgm};
  }
  const out=[];
  for(let i=0;i<5;i++) out.push({kind:'deep3', r:setup(510,p1,43)});
  for(let i=0;i<5;i++) out.push({kind:'bad-timing', r:setup(810,p1,5)});
  for(let i=0;i<5;i++) out.push({kind:'mid', r:setup(1250,p1,43)});
  return out;
})()`;
const r = await tools.browser.evaluate({ tabID, script });
return r.value;

