const script = `(() => {
  const E = AB.Engine;
  const p1=E.players[0], p2=E.players[1];
  const step = (n, dt=1/60) => { for (let i=0;i<n;i++){ E.update(dt); E.pressed={}; E.released={}; } };
  const orig = E.contestFactor;
  function shot(x, chargeFrames, shooter, defenderNear){
    E.paused=false; E.mode='match'; E.phase='live'; E.countdownT=0; E.clock=60; E.shotClock=14; E.deadT=0; E.deadNext=null; E.awaitShot=false; E.score=[0,0];
    shooter.stats={pts:0,fga:0,fgm:0,dunks:0,steals:0,blocks:0,bestStreak:0};
    for (const p of [p1,p2]){ p.dunk=null; p.charging=false; p.state='idle'; p.z=0; p.vz=0; p.grounded=true; p.hasBall=false; p.chargeT=0; p.chargePower=0; p.stumbleT=0; p.graceT=0; p.pickupLock=0; p.vx=0; }
    p1.x=x; p1.facing=p1.attackDir;
    p2.x=shooter===p1?(defenderNear?x+80:300):(defenderNear?x-80:1300); p2.z=0; p2.grounded=true;
    E.ball.state='held'; E.ball.catchable=false; E.ball.scoreable=false; E.ball.owner=null; E.giveBall(shooter);
    const act=shooter.idx===0?'KeyF':'KeyL';
    E.keys[act]=true; E.pressed[act]=true; step(1); E.keys[act]=false;
    step(chargeFrames);
    E.released[act]=true; step(1);
    step(170);
    return shooter.stats.fgm;
  }
  const variants = [
    {name:'base', pen:.09, fac:.30},
    {name:'p16f34', pen:.16, fac:.34},
    {name:'p22f34', pen:.22, fac:.34},
    {name:'p22f42', pen:.22, fac:.42}
  ];
  const out = [];
  for (const v of variants){
    E.contestFactor = function(shooter){
      const d = this.opponent(shooter);
      const dx = Math.abs(d.x - shooter.x);
      if (dx > 150) return 1;
      let c = 1 - (1 - Math.min(1, dx/150)) * v.fac;
      if (dx < 112) c -= v.pen;
      if (d.z > 20) c -= .12 * Math.min(1, Math.max(.25, d.z/140));
      if (d.blockT > 0) c -= .08;
      c -= d.data.attrs.block / 100 * .06;
      return Math.max(.46, Math.min(1, c));
    };
    let c3=0, cm=0, u3=0;
    for(let i=0;i<30;i++) c3 += shot(810,43,p1,true);
    for(let i=0;i<30;i++) cm += shot(1060,43,p1,true);
    for(let i=0;i<20;i++) u3 += shot(810,43,p1,false);
    out.push({name:v.name, c3, cm, u3});
  }
  E.contestFactor = orig;
  return out;
})()`;
const r = await tools.browser.evaluate({ tabID, script });
return r.value;

