(function(){
  if (!/[?&]qa=shots/.test(location.search)) return;
  function run(){
    const E = window.AB.Engine;
    const p1 = E.players[0], p2 = E.players[1];
    const step = (n) => { for (let i = 0; i < n; i++){ E.update(1/60); E.pressed = {}; E.released = {}; } };
    function shot(x, chargeFrames, shooter, defenderNear, gap){
      E.paused = false; E.mode = 'match'; E.phase = 'live'; E.countdownT = 0; E.clock = 60; E.shotClock = 14;
      E.deadT = 0; E.deadNext = null; E.awaitShot = false; E.score = [0, 0];
      shooter.stats = { pts:0, fga:0, fgm:0, dunks:0, steals:0, blocks:0, bestStreak:0 };
      for (const p of [p1, p2]){ p.dunk = null; p.charging = false; p.state = 'idle'; p.z = 0; p.vz = 0; p.grounded = true; p.hasBall = false; p.chargeT = 0; p.chargePower = 0; p.stumbleT = 0; p.graceT = 0; p.pickupLock = 0; p.vx = 0; }
      const def = shooter === p1 ? p2 : p1;
      shooter.x = x; shooter.facing = shooter.attackDir;
      def.x = defenderNear ? x + gap : (shooter === p1 ? 300 : 1300); def.z = 0; def.grounded = true; def.facing = -shooter.attackDir;
      E.ball.state = 'held'; E.ball.catchable = false; E.ball.scoreable = false; E.ball.owner = null; E.giveBall(shooter);
      const act = shooter.idx === 0 ? 'KeyF' : 'KeyL';
      E.keys[act] = true; E.pressed[act] = true; step(1); E.keys[act] = false;
      step(chargeFrames);
      E.released[act] = true; step(1);
      step(170);
      return shooter.stats.fgm;
    }
    const runN = (n, ...a) => { let m = 0; for (let i = 0; i < n; i++) m += shot(...a); return m + '/' + n; };
    const R = {
      p1_perfect_3: runN(20, 810, 43, p1, false),
      p1_deep3: runN(15, 510, 43, p1, false),
      p1_mid: runN(15, 1060, 43, p1, false),
      p1_bad: runN(20, 810, 5, p1, false),
      p1_tight3: runN(20, 810, 43, p1, true, 80),
      p1_semi3: runN(15, 810, 43, p1, true, 130),
      p1_tightMid: runN(20, 1060, 43, p1, true, 80),
      p2_perfect_3: runN(20, 790, 43, p2, false),
      p2_mid: runN(15, 350, 43, p2, false),
      p2_tight3: runN(20, 790, 43, p2, true, 80),
      p2_bad: runN(15, 790, 5, p2, false)
    };
    document.title = 'QARESULT ' + JSON.stringify(R);
  }
  if (document.readyState === 'complete') setTimeout(run, 400);
  else window.addEventListener('load', () => setTimeout(run, 400));
})();

